def _carceral_high_risk_template_lines(
    query: str,
    route: MatterRoute,
    passages: list[dict],
) -> list[str]:
    """Rescue source-gated custody workflows before broad legacy fallbacks."""
    q = query.lower()
    carceral_context = _has_any_term(q, (
        "jail", "prison", "prisoner", "undertrial", "convict", "custody",
        "lockup", "tihar", "mandoli", "rohini", "arthur road", "yerwada",
        "byculla", "puzhal", "district jail",
    ))

    custody_abuse_or_extortion = (
        route.label == "Custodial violence / police extortion"
        or _is_custody_abuse_extortion_query(q)
    )

    if (
        carceral_context
        and not custody_abuse_or_extortion
        and _has_any_term(q, (
        "tb", "tuberculosis", "insulin", "diabetic", "doctor", "hospital",
        "medical", "medicine", "medicines", "treatment", "psychiatrist",
        "suicidal", "suicide", "vomiting", "pregnant", "pregnancy",
        "heart", "chest pain", "wheelchair", "medical report",
        "medical examination", "assault by inmates",
        ))
        and _has_any_term(q, (
        "not getting", "not arranging", "not giving", "stopped", "hidden",
        "no report", "outside doctor", "outside hospital", "refuses",
        "refused", "says wait", "urgent", "can court", "family wants",
        "what can family file", "what urgent",
        ))
    ):
        custody_medical_lines = _custody_medical_care_template_lines(q, passages)
        if custody_medical_lines:
            return custody_medical_lines

    juvenile_signal = (
        _has_any_term(q, (
            "juvenile", "minor", "under 18", "under eighteen", "child accused",
            "minor accused", "age proof", "age determination",
            "school certificate", "birth certificate", "adult jail",
            "observation home", "jjb", "boy was 17", "17 at incident",
            "17 year", "16 year",
        ))
        and _has_any_term(q, (
            "accused", "police", "court", "jail", "lockup", "custody",
            "observation home", "remand", "adult court",
        ))
    )
    if juvenile_signal and not _is_adult_age_record_correction_query(q):
        juvenile_lines = _juvenile_age_custody_template_lines(q, passages)
        if juvenile_lines:
            return juvenile_lines

    undertrial_signal = carceral_context and _has_any_term(q, (
        "undertrial review", "under trial review", "undertrial review committee",
        "436a", "bnss 479", "section 479", "half maximum",
        "half sentence", "completed half", "maximum punishment",
        "trial not started", "trial not moving", "trial delay",
        "no witness", "not produced by video", "missed court dates",
        "missed video production", "missed video productions",
        "video production dates", "video productions",
        "jail internet failed", "video link failed", "video production failed",
        "custody increasing", "custody is", "custody-duration",
        "long custody",
    ))
    if undertrial_signal:
        if _has_any_term(q, ("lawyer", "legal aid", "dlsa", "not coming", "absent", "complain")):
            undertrial_legal_aid_lines = _undertrial_legal_aid_template_lines(passages)
            if undertrial_legal_aid_lines:
                return undertrial_legal_aid_lines
        undertrial_lines = _undertrial_review_template_lines(q, passages)
        if undertrial_lines:
            return undertrial_lines

    bail_release_signal = _has_any_term(q, (
        "bail granted", "granted bail", "court granted bail",
        "high court granted bail", "bail order", "release order",
        "court ordered release", "release warrant",
    )) and _has_any_term(q, (
        "not releasing", "not released", "still in jail", "release pending",
        "e-copy not received", "e copy not received", "warrant not received",
        "surety acceptance delayed", "surety verification pending",
        "jail says",
    ))
    if bail_release_signal:
        release_delay_lines = _bail_release_delay_template_lines(q, passages)
        if release_delay_lines:
            return release_delay_lines

    if _is_prison_records_query(q):
        records_lines = _prison_records_template_lines(q, passages)
        if records_lines:
            return records_lines

    if _is_prison_mulaqat_query(q):
        mulaqat_lines = _prison_mulaqat_template_lines(q, passages)
        if mulaqat_lines:
            return mulaqat_lines

    if custody_abuse_or_extortion:
        custody_abuse_lines = _police_torture_complaint_template_lines(q, passages)
        if custody_abuse_lines:
            return custody_abuse_lines

    if _is_arrest_production_delay_query(q):
        arrest_lines = _arrest_production_delay_template_lines(q, passages)
        if arrest_lines:
            return arrest_lines

    if _has_any_term(q, ("habeas", "illegal detention", "not telling station", "not telling where", "no magistrate production")):
        habeas_lines = _habeas_illegal_detention_template_lines(q, passages)
        if habeas_lines:
            return habeas_lines

    return []


