def _self_harm_crisis_template_lines(query: str, passages: list[dict]) -> list[str]:
    legal_aid = _find_passage_index(
        passages,
        title_terms=("legal services authorities",),
        anchor_terms=("/sec-12",),
    )
    mental_health = _find_passage_index(
        passages,
        title_terms=("mental healthcare",),
    )
    cite = legal_aid if legal_aid is not None else mental_health
    if cite is None:
        return []

    lines = ["**Short answer**"]
    if _has_any_term(query, ("suicide karne", "suicide karna", "marne ka mann", "marne ka man", "khud ko marna", "jaan dena")):
        lines.append(
            f"Because you said suicide karne ka mann after dowry harassment, treat this as an immediate safety crisis first: contact emergency help, a hospital, a trusted person, or a crisis helpline now, then use legal aid after you are safe [{cite}]."
        )
    elif re.search(r"[\u0900-\u097f]", query):
        lines.append(
            f"Because you are feeling like मरने/खुद को मारने after harassment, treat this as an immediate safety crisis first: contact emergency help, a hospital, a trusted person, or a crisis helpline now, then use legal aid after you are safe [{cite}]."
        )
    else:
        lines.append(
            f"Immediate safety comes before the dowry-harassment legal issue: contact emergency help, a hospital, a trusted person, or a crisis helpline now, then use legal aid after you are safe [{cite}]."
        )
    lines.append("**What you can do next**")
    lines.append(
        f"- If you may hurt yourself, stay with a trusted person and call local emergency services, go to the nearest hospital, or use a crisis helpline before preparing the legal complaint [{cite}]."
    )
    return lines


def _pocso_accused_template_lines(query: str, passages: list[dict]) -> list[str]:
    pocso33 = _find_passage_index(
        passages,
        title_terms=("protection of children from sexual offences",),
        anchor_terms=("/sec-33",),
    )
    pocso29 = _find_passage_index(
        passages,
        title_terms=("protection of children from sexual offences",),
        anchor_terms=("/sec-29",),
    )
    pocso_offence = _find_passage_index(
        passages,
        title_terms=("protection of children from sexual offences",),
        anchor_terms=("/sec-3", "/sec-4"),
    )
    bnss = _find_passage_index(
        passages,
        title_terms=("bharatiya nagarik suraksha",),
        anchor_terms=("/sec-35", "/sec-47", "/sec-480", "/sec-483", "/sec-528"),
    )
    crpc = _find_passage_index(
        passages,
        title_terms=("code of criminal procedure",),
        anchor_terms=("/sec-41", "/sec-50", "/sec-437", "/sec-438", "/sec-439"),
    )
    pocso_cite = pocso33 if pocso33 is not None else pocso29 if pocso29 is not None else pocso_offence
    procedure_cite = bnss if bnss is not None else crpc
    if pocso_cite is None and procedure_cite is None:
        return []

    lines = ["**Short answer**"]
    if pocso_cite is not None:
        lines.append(
            f"Treat this as an accused POCSO/criminal-defence route, not a survivor-service route; the POCSO Special Court source must be checked first [{pocso_cite}]."
        )
    if procedure_cite is not None:
        lines.append(
            f"The incident date and FIR sections decide the BNSS/CrPC bail and court-procedure route for an accused person [{procedure_cite}]."
        )
    lines.append("**What you can do next**")
    action_cite = procedure_cite if procedure_cite is not None else pocso_cite
    lines.append(
        f"- Get the FIR/complaint sections, complainant age facts, incident date, arrest or notice status, and court name; take them to DLSA or a criminal lawyer for bail and defence steps [{action_cite}]."
    )
    return lines


def _general_legal_intake_template_lines(query: str, passages: list[dict]) -> list[str]:
    legal_aid = _find_passage_index(
        passages,
        title_terms=("legal services authorities",),
        anchor_terms=("/sec-12",),
    )
    cpc = _find_passage_index(passages, title_terms=("code of civil procedure",))
    limitation = _find_passage_index(passages, title_terms=("limitation",))
    crpc = _find_passage_index(passages, title_terms=("code of criminal procedure",))
    cite = legal_aid if legal_aid is not None else cpc if cpc is not None else limitation if limitation is not None else crpc
    if cite is None:
        return []

    lines = [
        "**Short answer**",
        (
            f"I cannot safely classify this into a specific legal route from the facts given, so treat this as intake first rather than a final issue-specific answer; the legal-aid source is the safest starting source if you need help identifying the forum [{cite}]."
        ),
        "**What you can do next**",
        (
            f"- Re-ask with state/city, dates, who did what, documents/notices/FIR numbers if any, and the result you want; if there is urgent violence, arrest, self-harm risk, or medical danger, use emergency/police/hospital help first and then DLSA/legal aid [{cite}]."
        ),
    ]
    return lines


