    patient_phrase = "your mother" if "mother" in query else "your father" if "father" in query else "the patient"
    death_context = _has_any_term(query, ("died", "death", "passed away", "dead"))
    injection_context = _has_any_term(query, ("wrong injection", "injection", "injected"))
    records_or_billing = _has_any_term(query, (
        "medical records", "case papers", "hospital records", "not giving records",
        "not giving medical records", "detailed bill", "bill", "overcharge",
        "overcharged", "extra charge", "no receipt", "not giving bill",
    ))
    issue_phrase = (
        "hospital records/billing"
        if records_or_billing
        else "wrong injection and death"
        if injection_context and death_context
        else "wrong injection"
        if injection_context
        else "medical-treatment death"
        if death_context
        else "wrong-limb or wrong-surgery"
        if _has_any_term(query, ("wrong leg", "wrong limb", "wrong surgery", "wrong operation", "operated wrong"))
        else "medical-treatment"
    )
    records_only = _has_any_term(query, (
        "medical records", "case papers", "hospital records",
        "not giving records", "not giving medical records",
    )) and not _has_any_term(query, (
        "bill", "billing", "detailed bill", "overcharge", "overcharged",
        "wrong leg", "wrong limb", "wrong surgery", "wrong operation", "operated wrong",
    ))
    lines = ["**Short answer**"]
    if records_only and medical_ethics is not None:
        lines.append(
            f"For a private hospital not giving medical records after discharge, first make a written medical-record or case-paper request; the Medical Ethics Regulations source says records requested by the patient, authorised attendant, or legal authority should be acknowledged and issued within 72 hours [{medical_ethics}]."
        )
    elif records_only and clinical is not None:
        lines.append(
            f"For a private hospital not giving medical records after discharge, first make a written medical-record or case-paper request and keep the discharge summary, bill, payment proof, and hospital reply; the Clinical Establishments source is only a records-maintenance/reporting source to verify, not a direct patient-copy rule [{clinical}]."
        )
    elif records_or_billing and clinical is not None:
        lines.append(
            f"Treat this first as a hospital records/billing grievance, not as a generic negligence claim; the Clinical Establishments Act source is the hospital-records/charges source to verify [{clinical}]."
        )
    if consumer2 is not None:
        if records_only:
            lines.append(
                f"Use the consumer-law source only as the backup service-deficiency route if the hospital still refuses records after a written request or grievance [{consumer2}]."
            )
        else:
            lines.append(
                f"Treat this first as a hospital service-deficiency or medical-negligence question only if the medical records support the {issue_phrase} facts; the Consumer Protection Act source is the consumer-law base to check [{consumer2}]."
            )
            if death_context or injection_context:
                lines.append(
                    f"For {issue_phrase}, compensation is normally built from the treatment record, cause-of-death or injury record, expert/medical-council material, and the District Commission consumer complaint route; keep police only for separate criminal-negligence facts [{consumer2}]."
                )
    elif clinical is not None and not records_or_billing:
        lines.append(
            f"Treat this first as a hospital records/billing grievance, not as a generic negligence claim; the Clinical Establishments Act source is the hospital-records/charges source to verify [{clinical}]."
        )
    if consumer35 is not None:
        lines.append(
            f"The Consumer Protection Act complaint source gives the consumer-forum filing route, so do not route this only as a police/FIR issue unless separate criminal-negligence facts are alleged [{consumer35}]."
        )
    if consumer39 is not None:
        lines.append(
            f"The Consumer Protection Act relief source is relevant for refund, replacement, removal of deficiency, compensation, or similar consumer-forum relief depending on proof [{consumer39}]."
        )
    if clinical is not None:
        lines.append(
            f"For hospital records, case papers, itemised bills, or overcharging facts, separately verify the Clinical Establishments source for records-maintenance/reporting or authority action before relying only on consumer-forum judgments [{clinical}]."
        )
    action_cite = medical_ethics if records_only and medical_ethics is not None else clinical if records_or_billing and clinical is not None else consumer35 if consumer35 is not None else consumer39 if consumer39 is not None else consumer2 if consumer2 is not None else clinical
    if records_only:
        lines.extend([
            "**What you can do next**",
            f"- Ask the private hospital in writing for the medical records or case papers after discharge; keep the request, discharge summary, bill/payment proof, patient ID/authority letter, and hospital reply before approaching the clinical-establishment authority, hospital grievance desk, medical council, or District Commission as the facts support [{action_cite}].",
        ])
        return lines
    lines.extend([
        "**What you can do next**",
        f"- Collect {patient_phrase}'s consent form, prescription/injection chart, operation notes if any, discharge summary, death certificate or injury record where relevant, medical-record request, itemised bill, payment receipts, photos if any, and the written hospital reply before filing a hospital grievance, clinical-establishment authority complaint, medical-council complaint, or District Commission complaint for compensation or refund where proof supports it [{action_cite}].",
    ])
    return lines


