            ("developer salary dispute", "python developer", "developer", "software engineer"),
            ("domestic-worker wage dispute", "domestic worker"),
            ("construction-site overtime dispute", "construction site", "overtime"),
            ("migrant-worker wage dispute", "migrant", "supaul", "bihar", "came from"),
            ("munshi/thekedar wage dispute", "munshi", "thekedar", "contractor"),
