    wage_cite = wage17 if wage17 is not None else wage45 if wage45 is not None else wage18
    id_cite = id25ffa if id25ffa is not None else id25fff if id25fff is not None else id25f
    if id_cite is None and wage_cite is None:
        return []

    worker_count = _extract_worker_count(query)
    worker_phrase = f"{worker_count} workers" if worker_count is not None else "workers"
    migrant_phrase = "Tamil/migrant " if _has_any_term(query, ("tamil migrant", "migrant")) else ""
    closure_subject = (
        "factory/plant closure"
        if _has_any_term(query, ("factory", "plant", "mill", "unit", "garment", "tiruppur"))
        else "company/undertaking closure"
    )
    lines = ["**Short answer**"]
    if id_cite is not None:
        lines.append(
            f"A sudden factory closure / sudden {closure_subject} affecting {migrant_phrase}{worker_phrase} with no notice is not only an unpaid-salary issue; verify the closure/retrenchment track under the Industrial Disputes Act source [{id_cite}]."
        )
        lines.append(
            f"For the closure/retrenchment track, preserve the no-notice facts, worker count, last working date, and whether notice wages or retrenchment/closure compensation were paid under the Industrial Disputes Act source [{id_cite}]."
        )
    if id25f is not None and id25f != id_cite:
        lines.append(
            f"If the employer treats this as retrenchment, check the Industrial Disputes Act notice and compensation source separately from the wage-arrears claim [{id25f}]."
        )
        lines.append(
            f"Section 25F says retrenchment of a qualifying workman requires notice or notice wages and retrenchment compensation, so keep that calculation separate from salary arrears [{id25f}]."
        )
    elif id_cite is not None:
        lines.append(
            f"The Industrial Disputes Act source is the authority to check for closure or retrenchment notice, notice wages, and compensation before accepting a sudden workplace shutdown as final [{id_cite}]."
        )
    if wage_cite is not None:
        lines.append(
            f"The two months pending salary remains a Code on Wages payment/claims-authority issue, so keep the arrears calculation and closure notice facts together [{wage_cite}]."
        )
        lines.append(
            f"For the unpaid salary side, the wage claim should go to the wage authority or Labour Commissioner with month-wise arrears even while the closure/retrenchment track is checked separately [{wage_cite}]."
        )
        lines.append(
            f"The wage source gives the wage-authority route for unpaid wages, so list each worker's two-month arrears instead of filing only a general factory-closure complaint [{wage_cite}]."
        )
    action_cites = "".join(f"[{idx}]" for idx in (id_cite, wage_cite) if idx is not None)
    lines.extend([
        "**What you can do next**",
        f"- Make a worker list with names, home State if migrant, joining dates, last working date, wage rate, two-month arrears, closure/no-notice proof, workplace/factory address, and employer/contractor details; file a written complaint with the Labour Commissioner/wage authority/DLSA using both the closure/retrenchment and wage-arrears tracks {action_cites}.",
    ])
    return lines


