def _gig_platform_worker_template_lines(query: str, passages: list[dict]) -> list[str]:
    ss113 = _find_passage_index(passages, title_terms=("code on social security",), anchor_terms=("/sec-113",))
    ss114 = _find_passage_index(passages, title_terms=("code on social security",), anchor_terms=("/sec-114",))
    ss112 = _find_passage_index(passages, title_terms=("code on social security",), anchor_terms=("/sec-112",))
    wage45 = _find_passage_index(passages, title_terms=("code on wages",), anchor_terms=("/sec-45",))
    wage17 = _find_passage_index(passages, title_terms=("code on wages",), anchor_terms=("/sec-17",))
    wage18 = _find_passage_index(passages, title_terms=("code on wages",), anchor_terms=("/sec-18",))
    id2 = _find_passage_index(passages, title_terms=("industrial disputes",), anchor_terms=("/sec-2",))
    id25f = _find_passage_index(passages, title_terms=("industrial disputes",), anchor_terms=("/sec-25F",))
    id_cite = id25f if id25f is not None else id2
    if ss113 is None and ss114 is None and ss112 is None and wage17 is None and wage18 is None and wage45 is None and id_cite is None:
        return []
    main_cite = ss113 if ss113 is not None else ss114 if ss114 is not None else ss112 if ss112 is not None else wage45 if wage45 is not None else wage17 if wage17 is not None else wage18 if wage18 is not None else id_cite
    platform = _present_terms_phrase(
        query,
        (("Swiggy", "swiggy"), ("Zomato", "zomato"), ("Blinkit", "blinkit"), ("Zepto", "zepto"), ("Urban Company", "urban company"), ("Ola", "ola"), ("Uber", "uber"), ("Rapido", "rapido")),
        fallback="the platform",
    )
    rating_issue = _has_any_term(query, ("customer abused", "customer complaint", "1 star", "one star", "rating", "spam"))
    strike_or_termination_issue = _has_any_term(query, (
        "3 strike", "three strike", "strike system", "termination", "terminated",
        "unfair termination", "deactivated", "suspended",
    ))
    account_issue = "3-strike termination/deactivation" if strike_or_termination_issue else "worker ID block"
    lines = ["**Short answer**"]
    if ss113 is not None:
        issue_phrase = " after the customer-abuse, one-star, rating, or spam complaint" if rating_issue else ""
        lines.append(
            f"For a {platform} {account_issue}{issue_phrase}, file the platform appeal first and keep the Code on Social Security source as the gig/platform-worker registration route to verify [{ss113}]."
        )
    if ss114 is not None:
        lines.append(
            f"The Code on Social Security source also contemplates social-security schemes for gig workers and platform workers, including accident, health, maternity, and other benefits [{ss114}]."
        )
    wage_cite = wage45 if wage45 is not None else wage17 if wage17 is not None else wage18
    if wage_cite is not None:
        lines.append(
            f"If the ID block also leaves earned payout or wages unpaid, use the Code on Wages source only for that payment/claim side, not as a substitute for the account appeal [{wage_cite}]."
        )
    if id_cite is not None:
        lines.append(
            f"The Industrial Disputes Act route matters only if the facts show employee/workman status or a retrenchment/termination dispute, so avoid promising reinstatement before checking the contract and control over work [{id_cite}]."
        )
    elif ss112 is not None:
        lines.append(
            f"The facilitation-centre source supports asking where gig/platform worker registration or scheme help is available [{ss112}]."
        )
    lines.append("**What you can do next**")
    id_suffix = f"[{id_cite}]" if id_cite is not None and id_cite != main_cite else ""
    lines.append(
        f"- Preserve the {platform} ID-block message, strike/deactivation notice, customer-abuse or one-star/spam screenshots, appeal ticket, platform contract/proof, service-partner contract, ratings, and payout ledger; ask the platform for written reasons and release of undisputed earnings before choosing social-security or conditional labour-law escalation [{main_cite}]{id_suffix}."
    )
    return lines


