def _christian_widow_succession_template_lines(query: str, passages: list[dict]) -> list[str]:
    sec32 = _find_passage_index(passages, title_terms=("indian succession",), anchor_terms=("/sec-32",))
    sec33 = _find_passage_index(passages, title_terms=("indian succession",), anchor_terms=("/sec-33",))
    sec33_text = _find_passage_index_by_text(
        passages,
        title_terms=("indian succession",),
        text_terms=("where intestate has left widow", "one-third of his property"),
    )
    sec33a = _find_passage_index(passages, title_terms=("indian succession",), anchor_terms=("/sec-33A", "/sec-33-a"))
    sec37 = _find_passage_index(passages, title_terms=("indian succession",), anchor_terms=("/sec-37",))
    if sec32 is None and sec33 is None and sec33_text is None and sec33a is None and sec37 is None:
        return []
    property_phrase = "husband's self-acquired property" if _has_any_term(query, ("self acquired", "self-acquired", "self earned")) else "husband's intestate estate/property"
    lineal_descendant_context = _has_any_term(query, ("child", "children", "son", "daughter", "lineal descendant", "lineal descendants"))
    lines = ["**Short answer**"]
    if sec32 is not None:
        lines.append(
            f"For a Christian widow asking about {property_phrase}, start with the Indian Succession Act intestate-succession source, not a police complaint route [{sec32}]."
        )
    if sec33a is not None and not lineal_descendant_context:
        lines.append(
            f"Section 33A is the specific Indian Succession Act source to check for a widow's share where the deceased left a widow but no lineal descendants and the estate value condition is relevant [{sec33a}]."
        )
    elif sec33 is not None:
        lines.append(
            f"Section 33 is the Indian Succession Act source to check for the widow's share when the deceased left a widow with lineal descendants or kindred [{sec33}]."
        )
    elif sec33_text is not None:
        lines.append(
            f"The same Indian Succession Act passage contains the Section 33 widow-share rule: if the deceased left a widow and lineal descendants, one-third belongs to the widow and the remaining two-thirds goes to the lineal descendants [{sec33_text}]."
        )
    if sec37 is not None:
        lines.append(
            f"Stepchildren do not become heirs just by being stepchildren; first confirm whether they are legally children/lineal descendants or only kindred under the Indian Succession Act structure [{sec37}]."
        )
    action_cite = sec33a if sec33a is not None else sec33 if sec33 is not None else sec33_text if sec33_text is not None else sec32 if sec32 is not None else sec37
    if _has_any_term(query, ("mutation", "mutate", "transfer", "names", "their names", "only in their name", "only in their names")):
        lines.append(
            f"If the children are trying to mutate or transfer the property only in their names, object with the death certificate, marriage proof, family tree, and property papers because the widow's succession share must be checked before revenue records are changed [{action_cite}]."
        )
    lines.extend([
        "**What you can do next**",
        f"- Prepare the death certificate, marriage proof, no-will/will status, family tree including stepchildren/adopted children if any, and property papers; take those to DLSA or a succession lawyer before filing mutation or succession proceedings [{action_cite}].",
    ])
    return lines


