def _legal_aid_eligibility_template_lines(query: str, passages: list[dict]) -> list[str]:
    lsa12 = _find_passage_index(
        passages,
        title_terms=("legal services authorities",),
        anchor_terms=("/sec-12",),
    )
    lsa9 = _find_passage_index(
        passages,
        title_terms=("legal services authorities",),
        anchor_terms=("/sec-9",),
    )
    lsa13 = _find_passage_index(
        passages,
        title_terms=("legal services authorities",),
        anchor_terms=("/sec-13",),
    )
    article39a = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-39a", "/sec-39A", "/sec-39"),
    )
    article22 = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-22",),
    )
    bnss47 = _find_passage_index(
        passages,
        title_terms=("bharatiya nagarik suraksha",),
        anchor_terms=("/sec-47",),
    )
    bnss58 = _find_passage_index(
        passages,
        title_terms=("bharatiya nagarik suraksha",),
        anchor_terms=("/sec-58",),
    )
    bnss57 = _find_passage_index(
        passages,
        title_terms=("bharatiya nagarik suraksha",),
        anchor_terms=("/sec-57",),
    )
    crpc50 = _find_passage_index(
        passages,
        title_terms=("code of criminal procedure",),
        anchor_terms=("/sec-50",),
    )
    crpc57 = _find_passage_index(
        passages,
        title_terms=("code of criminal procedure",),
        anchor_terms=("/sec-57",),
    )
    lsa = lsa12 if lsa12 is not None else lsa13 if lsa13 is not None else lsa9
    if lsa is None:
        return []
    lines = ["**Short answer**"]
    custody_context = _has_any_term(query, (
        "arrest", "arrested", "custody", "detained", "lockup",
        "inside lockup", "jail", "prison", "remand", "first remand",
        "police station", "court remand", "production before magistrate",
        "accused", "undertrial",
    ))
    custody_negated = _has_any_term(query, (
        "no arrest", "not arrested", "not criminal case", "not a criminal case",
        "no criminal case", "not in custody", "not detained", "no detention",
        "no police custody",
    ))
    explicit_access_block = _has_any_term(query, (
        "not allowing lawyer", "lawyer not allowed",
        "not allowing advocate", "advocate not allowed",
        "lawyer can meet only after", "only after confession",
        "confession statement", "lawyer meeting refused",
        "lawyer access blocked",
    ))
    lawyer_need = _has_any_term(query, (
        "lawyer meeting", "lawyer meet", "jail superintendent",
        "no lawyer", "cannot afford advocate", "can't afford advocate",
        "cant afford advocate", "cannot afford lawyer", "can't afford lawyer",
        "cant afford lawyer", "private lawyer", "free lawyer",
        "legal aid lawyer", "first remand",
    ))
    civil_affordability_context = _has_any_term(query, (
        "property", "partition", "civil suit", "civil case", "land",
        "tenant", "rent", "maintenance case", "consumer case",
        "consumer complaint", "phone company", "service provider",
        "labour case", "family case", "divorce", "inheritance",
        "lawyer expensive", "private lawyer expensive", "too expensive",
    ))
    if custody_negated and civil_affordability_context and not explicit_access_block:
        custody_context = False
    blocked_meeting = explicit_access_block or (
        custody_context and lawyer_need and not (
            civil_affordability_context and not _has_any_term(query, ("arrest", "arrested", "custody", "detained", "jail", "prison", "remand", "lockup"))
        )
    )
    if blocked_meeting:
        lines.append(
            f"If the jail superintendent is not allowing a lawyer meeting, or the family cannot afford an advocate for an arrested person or prisoner, treat it as a custody legal-aid and lawyer-access issue for free legal services first, not a generic jail complaint [{lsa}]."
        )
        if _has_any_term(query, ("confession", "inside lockup", "lawyer can meet only after")):
            lines.append(
                f"Do not treat 'lawyer only after confession' as normal legal process; ask DLSA/court duty counsel to record the lawyer-access blockage and custody stage before any statement is relied on [{lsa}]."
            )
        if article22 is not None:
            lines.append(
                f"Article 22 is also a source to keep with the file because it protects consultation and defence by a legal practitioner after arrest [{article22}]."
            )
        custody_cite = bnss47 if bnss47 is not None else bnss58 if bnss58 is not None else bnss57 if bnss57 is not None else crpc50 if crpc50 is not None else crpc57
        if custody_cite is not None:
            lines.append(
                f"Keep the arrest/remand or jail-production papers with the legal-aid request, because the custody-procedure source helps the assigned lawyer verify the case stage [{custody_cite}]."
            )
        if bnss47 is not None and custody_cite != bnss47:
            lines.append(
                f"For current BNSS matters, keep the BNSS arrest-information source with the file for grounds-of-arrest and custody-stage lawyer-access checks [{bnss47}]."
            )
        if crpc50 is not None and custody_cite != crpc50:
            lines.append(
                f"If the older CrPC route applies, keep the CrPC arrest-information source with the file as the legacy comparison for grounds of arrest and custody-stage lawyer access [{crpc50}]."
            )
    elif custody_context or (
        not custody_negated
        and _has_any_term(query, ("arrest", "arrested", "jail", "custody", "prison", "brother", "husband"))
        and not civil_affordability_context
    ):
        lines.append(
            f"For an arrested person or prisoner who needs a lawyer, start with the Legal Services Authorities Act source; Section 12 is the eligibility source for free legal services where the authority applies the income or category rules [{lsa}]."
        )
    elif civil_affordability_context:
        dispute_phrase = (
            "property partition suit"
            if _has_any_term(query, ("property", "partition"))
            else "consumer complaint"
            if _has_any_term(query, ("consumer complaint", "consumer case", "phone company", "service provider", "warranty", "refund", "defective"))
            else "labour case"
            if _has_any_term(query, ("labour case", "wage", "wages", "salary", "termination"))
            else "family case"
            if _has_any_term(query, ("family case", "divorce", "maintenance case", "inheritance"))
            else "civil/family/consumer/labour case"
        )
        lines.append(
            f"For a {dispute_phrase}, legal aid is about getting help with lawyer assignment, filing, reply, or court representation if you qualify; it does not by itself decide the ownership or merits of the case [{lsa}]."
        )
    else:
        lines.append(
            f"For free legal-aid eligibility, start with the Legal Services Authorities Act source; Section 12 is the eligibility source for persons entitled to legal services, including income or category based eligibility where the authority applies it [{lsa}]."
        )
    if lsa9 is not None:
        lines.append(
            f"The District Legal Services Authority route is the local filing point to approach with your district, case type, and proof documents [{lsa9}]."
        )
    if article39a is not None:
        lines.append(
            f"Article 39A is a constitutional support principle for equal justice and free legal aid, but the application route should still be checked under the Legal Services Authorities Act and DLSA/SLSA procedure [{article39a}]."
        )
    lines.extend([
        "**What you can do next**",
    ])
    if blocked_meeting:
        lines.append(
            f"- Take ID proof, BPL/income/category proof if relied on, jail/prison name, lawyer-meeting refusal details, and any court, police, arrest, remand, or jail papers to the nearest DLSA/TLSC or SLSA help desk and ask for a written legal-aid application acknowledgement [{lsa}]."
        )
    elif custody_context:
        lines.append(
            f"- Take ID proof, income/category proof if relied on, arrest/remand or jail papers, FIR/case details, and next hearing date to DLSA/TLSC, SLSA, or the court legal-aid desk and ask for written assignment status [{lsa}]."
        )
    else:
        if civil_affordability_context:
            property_docs = (
                "partition papers, title/revenue records, family tree, notices, and pending case number"
                if _has_any_term(query, ("property", "partition"))
                else "consumer notice/complaint papers, invoice/order ID, warranty or service chats, rejection/refusal proof, income/category proof, and forum/case number if already filed"
                if _has_any_term(query, ("consumer complaint", "consumer case", "phone company", "service provider", "warranty", "refund", "defective"))
                else "case papers, notices, income/category proof, and pending case number"
            )
            help_phrase = (
                "the consumer complaint"
                if _has_any_term(query, ("consumer complaint", "consumer case", "phone company", "service provider", "warranty", "refund", "defective"))
                else "the pending civil case"
            )
            lines.append(
                f"- Take ID proof, income/category proof if relied on, {property_docs} to DLSA/TLSC, SLSA, or the court/legal-aid desk; ask specifically for lawyer assignment or filing help for {help_phrase} [{lsa}]."
            )
            return lines
        lines.append(
            f"- Take ID proof, income/category proof if relied on, case papers or notices, court/forum name, district, and a short note on the help needed to DLSA/TLSC, SLSA, or the court legal-aid desk and ask for a written application acknowledgement [{lsa}]."
        )
    return lines


def _ibc_nclt_template_lines(query: str, passages: list[dict]) -> list[str]:
    ibc7 = _find_passage_index(
        passages,
        title_terms=("insolvency and bankruptcy",),
        anchor_terms=("/sec-7",),
    )
    ibc8 = _find_passage_index(
        passages,
        title_terms=("insolvency and bankruptcy",),
        anchor_terms=("/sec-8",),
    )
    ibc9 = _find_passage_index(
        passages,
        title_terms=("insolvency and bankruptcy",),
        anchor_terms=("/sec-9",),
    )
    ibc54 = _find_passage_index(
        passages,
        title_terms=("insolvency and bankruptcy",),
        anchor_terms=("/sec-54A", "/sec-54-a", "/sec-54"),
    )
    ibc_fallback = _find_passage_index(
        passages,
        title_terms=("insolvency",),
    )
    companies = _find_passage_index(
        passages,
        title_terms=("companies act",),
    )
    ibc_any = ibc54 if ibc54 is not None else ibc9 if ibc9 is not None else ibc8 if ibc8 is not None else ibc7 if ibc7 is not None else ibc_fallback
    if ibc_any is None:
        return []
    prepack = _has_any_term(query, ("pre pack", "pre-pack", "prepack", "pre packaged", "pre-packaged", "own company"))
    lines = ["**Short answer**"]
    ibc_title = next(
        (
            str(p.get("title") or "").strip()
            for p in passages
            if p.get("index") == ibc_any and str(p.get("title") or "").strip()
        ),
        "",
    )
    if ibc_title:
        lines.append(f"Source to verify first: {ibc_title} [{ibc_any}].")
    if prepack and ibc54 is not None:
        lines.append(
            f"For a pre-pack insolvency or recovery question about your own company, start with the IBC pre-packaged insolvency source and check debtor/MSME eligibility before treating it as an ordinary creditor petition [{ibc54}]."
        )
    elif ibc7 is not None and _has_any_term(query, ("financial creditor", "loan", "debt")) and not _has_any_term(query, ("operational creditor", "invoice", "goods", "service")):
        lines.append(
            f"If you are a financial creditor, the IBC financial-creditor application source is the NCLT route to check with debt, default, and record-of-default proof [{ibc7}]."
        )
    if ibc8 is not None:
        lines.append(
            f"If you are an operational creditor, the IBC demand-notice source is the recovery starting point to check before any Section 9-style NCLT application [{ibc8}]."
        )
    if ibc9 is not None:
        lines.append(
            f"After the demand-notice step and no valid payment/dispute response, the IBC operational-creditor application source is the NCLT filing route and insolvency-recovery filing route to verify [{ibc9}]."
        )
    if not lines[1:] and ibc_any is not None:
        lines.append(
            f"For an NCLT insolvency filing, the cited IBC source is the source to check; classify the debt as financial debt, operational debt, or debtor-side pre-pack before choosing the filing route [{ibc_any}]."
        )
    if companies is not None:
        lines.append(
            f"Use the Companies Act source only for company identity, ROC, or filing-status records [{companies}]; the insolvency petition route itself must still be verified under the cited IBC source [{ibc_any}]."
        )
    lines.append("**What you can do next**")
    if prepack:
        lines.append(
            f"- Prepare the MSME/corporate-debtor pre-pack recovery and restructuring file with board/member approval status, base resolution plan, debt/default record, financial statements, creditor list, and proposed resolution-professional details; speak to an insolvency professional before any NCLT PPIRP filing [{ibc_any}]."
        )
    else:
        lines.append(
            f"- Prepare the IBC recovery file with debt type, amount, default date, invoices/contract, company details, demand notice and dispute/payment reply status; speak to an insolvency professional before filing the Section 9/NCLT form [{ibc_any}]."
        )
    return lines


