def _undertrial_review_template_lines(query: str, passages: list[dict]) -> list[str]:
    bnss479 = _find_passage_index(
        passages,
        title_terms=("bharatiya nagarik suraksha",),
        anchor_terms=("/sec-479",),
    )
    crpc436a = _find_passage_index(
        passages,
        title_terms=("code of criminal procedure",),
        anchor_terms=("/sec-436A", "/sec-436-a", "/sec-436"),
    )
    lsa = _find_passage_index(
        passages,
        title_terms=("legal services authorities",),
        anchor_terms=("/sec-9", "/sec-12"),
    )
    article21 = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-21",),
    )
    cite = bnss479 if bnss479 is not None else crpc436a if crpc436a is not None else lsa if lsa is not None else article21
    if cite is None:
        return []

    person = "the undertrial"
    if _has_any_term(query, ("father", "papa")):
        person = "your father"
    elif _has_any_term(query, ("brother", "bhai")):
        person = "your brother"
    elif _has_any_term(query, ("women", "woman", "pregnant", "wife")):
        person = "the women undertrials"

    speedy_trial_context = _has_any_term(query, (
        "speedy trial", "trial not started", "trial has not started",
        "trial never started", "not started", "2 yrs", "2 years",
        "two years", "18 months", "20 months", "murder trial", "long custody",
        "trial slow", "slow trial", "half maximum", "half of maximum",
        "completed half", "one-half", "not produced by video",
        "not produced", "missed court dates", "missed video production",
        "missed video productions", "video production dates", "video productions",
        "jail internet failed", "video link failed", "video production failed",
        "custody increasing", "many dates",
    ))
    not_produced_context = _has_any_term(query, (
        "not produced", "not produced by video", "video for many dates",
        "missed court dates", "missed video production",
        "missed video productions", "video production dates", "video productions",
        "jail internet failed", "video link failed", "video production failed",
        "many dates", "custody increasing",
    ))
    half_sentence_context = _has_any_term(query, (
        "half sentence", "half-sentence", "half maximum", "half of maximum",
        "half sentence rule", "half-maximum", "436a", "436-a",
    ))
    chargesheet_stalled_context = _has_any_term(query, (
        "chargesheet filed", "charge sheet filed", "trial not moving",
        "trial slow", "not moving",
    ))
    jail_context = "Tihar jail" if _has_any_term(query, ("tihar",)) else "jail"
    offence_context = "murder trial" if _has_any_term(query, ("murder",)) else "trial"
    duration_context = "about two years" if _has_any_term(query, ("2 yrs", "2 years", "two years")) else "a long time"
    legacy_undertrial_query = _has_any_term(query, (
        "crpc 436a", "436a", "436-a", "section 436a", "section 436-a",
        "2019", "2020", "2021", "2022", "2023",
    ))

    lines = ["**Short answer**"]
    if not_produced_context:
        review_cite = article21 if article21 is not None else lsa if lsa is not None else cite
        lines.append(
            f"The review forum is the jail legal-aid clinic/DLSA or Under Trial Review Committee, and the same trial court can also be moved, because repeated non-production by video while custody keeps increasing is a liberty and speedy-trial review issue [{review_cite}]."
        )
    if half_sentence_context:
        half_cite = bnss479 if bnss479 is not None else crpc436a if crpc436a is not None else cite
        lines.append(
            f"Yes, the half-sentence or half-maximum custody check can still be made even after the charge-sheet is filed; calculate actual detention from first remand and compare it with the maximum punishment and statutory exclusions before asking the court/UTRC for review [{half_cite}]."
        )
    elif chargesheet_stalled_context:
        stalled_cite = article21 if article21 is not None else lsa if lsa is not None else cite
        lines.append(
            f"If the charge-sheet is filed but the trial is not moving, keep a separate trial-delay note with missed dates and production failures for DLSA/UTRC or trial-court review [{stalled_cite}]."
        )
    if speedy_trial_context and article21 is not None:
        lines.append(
            f"If {person} is in {jail_context} for {duration_context} and the {offence_context} has not started, treat it as an Article 21 speedy-trial/right-to-liberty issue, plus a separate BNSS/CrPC undertrial custody-duration review; it is not automatic release, but it is a concrete legal-aid/court-review point [{article21}]."
        )
    if legacy_undertrial_query and crpc436a is not None:
        lines.append(
            f"For an older criminal case asking whether the CrPC 436A route is available, use the CrPC Section 436A source first: compare half of the maximum imprisonment with actual undertrial detention, subject to the statutory exclusions and any recorded court reasons [{crpc436a}]."
        )
        if bnss479 is not None:
            lines.append(
                f"Keep BNSS Section 479 as the current-law comparison point, but do not let it replace the CrPC 436A check for a 2019/legacy case [{bnss479}]."
            )
    elif bnss479 is not None:
        lines.append(
            f"For {person}, the BNSS Section 479 source is the BNSS source for undertrial custody-duration review; compare it with the offence maximum, actual detention period, and statutory exclusions [{bnss479}]."
        )
        if crpc436a is not None:
            lines.append(
                f"Also keep the CrPC Section 436A source as the legacy/transitional comparison for older FIRs or pre-BNSS custody periods; do not mix the two regimes without checking the incident and custody dates [{crpc436a}]."
            )
    elif crpc436a is not None:
        lines.append(
            f"For {person}, the CrPC Section 436A source is the older-regime undertrial custody-duration source to compare with the offence maximum and actual detention period [{crpc436a}]."
        )
    if article21 is not None and (
        speedy_trial_context
        or not_produced_context
        or _has_any_term(query, ("3 yrs", "3 years", "70 yrs", "65 yr", "diabetic", "pregnant", "tb", "medical", "old"))
    ):
        if speedy_trial_context:
            if len([line for line in lines if f"[{article21}]" in line]) == 0:
                lines.append(
                    f"If the trial has not started after a long custody period, keep Article 21 speedy-trial delay as a separate review point along with the BNSS/CrPC custody-duration calculation [{article21}]."
                )
        else:
            lines.append(
                f"Age, pregnancy, serious illness, or long custody should be kept as a separate Article 21 liberty and medical-vulnerability note for legal-aid or court review [{article21}]."
            )
    if lsa is not None:
        lines.append(
            f"The Legal Services Authorities source supports taking the jail/DLSA route for legal-aid assistance with the undertrial review papers [{lsa}]."
        )
    lines.append("**What you can do next**")
    custody_cite = bnss479 if bnss479 is not None else crpc436a
    if legacy_undertrial_query and crpc436a is not None:
        custody_cite = crpc436a
    if custody_cite is not None:
        lines.append(
            f"- Prepare a one-page custody chart with first remand date, FIR/charge sections, maximum punishment, charge-sheet/trial stage, missed physical/video production dates, whether the trial has started, half-maximum calculation, speedy-trial delay facts, prior bail orders, age/medical proof, and jail location; ask the jail legal-aid clinic, DLSA, or Under Trial Review Committee/trial court to consider statutory review or bail using the cited custody-duration source [{custody_cite}]."
        )
    elif lsa is not None:
        lines.append(
            f"- Prepare the same custody chart and ask the jail legal-aid clinic or DLSA to identify the applicable BNSS/CrPC custody-duration provision and move the Under Trial Review Committee or trial court; the cited Legal Services Authorities source supports the legal-aid assistance route [{lsa}]."
        )
    elif article21 is not None:
        lines.append(
            f"- Prepare the custody and medical/age papers and ask a legal-aid lawyer to check the statutory undertrial-release provision separately; the cited Article 21 source supports keeping liberty and medical-vulnerability as a review point [{article21}]."
        )
    return lines


def _prison_mulaqat_template_lines(query: str, passages: list[dict]) -> list[str]:
    delhi_rules = _find_passage_index(
        passages,
        title_terms=("delhi prison rules", "delhi prisons rules"),
        anchor_terms=(
            "/rule-2-mulaqat",
            "/rule-595-599",
            "/rule-601-606",
            "/rule-613-616",
            "/rule-619-1029-books",
            "/prisoners-rights-contact-books",
        ),
    )
    prisons = _find_passage_index(
        passages,
        title_terms=("prisons act", "prisons"),
        anchor_terms=("/sec-59",),
    )
    article21 = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-21",),
    )
    if delhi_rules is None and prisons is None and article21 is None:
        return []
    lines = ["**Short answer**"]
    book_context = _has_any_term(query, ("book", "books", "library", "newspaper", "magazine", "reading material"))
    delhi_context = _has_any_term(query, ("tihar", "delhi", "mandoli", "rohini"))
    if not delhi_context:
        delhi_rules = None
    if delhi_rules is not None:
        if book_context:
            lines.append(
                f"For Tihar/Delhi prison books, start with the Delhi Prison Rules permitted-item route: ask the Jail Superintendent for the permitted-book/library or screening route, rather than treating this as bail or parole [{delhi_rules}]."
            )
        else:
            lines.append(
                f"For Tihar/Delhi mulaqat, the Delhi Prison Rules source is the concrete local source for permission, interview timing, normal half-hour duration, possible Superintendent extension, and recorded reasons for refusal [{delhi_rules}]."
            )
            if _has_any_term(query, ("video call", "video calls", "video slot", "call slot", "server down", "slot failed")):
                lines.append(
                    f"If the video-call slot failed repeatedly or staff say the server is down, ask the Jail Superintendent for a written slot/status order, the next available slot, and the recorded reason instead of treating it as a parole or bail issue [{delhi_rules}]."
                )
                if article21 is not None:
                    lines.append(
                        f"Keep the Constitution Article 21 source in the file if repeated failed video-call access or no written reason blocks family/legal contact in a way that appears arbitrary [{article21}]."
                    )
            if _has_any_term(query, ("visitor list", "removed my name", "address check", "address verification")):
                lines.append(
                    f"If a visitor name was removed or held up after address check, ask for the visitor-list rule, verification status, and written reasons from the Superintendent before escalating to DLSA or writ review [{delhi_rules}]."
                )
                if article21 is not None:
                    lines.append(
                        f"Keep the Constitution Article 21 source in the file if visitor-list removal or address-check delay blocks family/legal contact without written reasons or appears arbitrary [{article21}]."
                    )
    elif prisons is not None:
        state_phrase = "Because the prison/state rule is not pinned down in the retrieved sources, "
        if delhi_context:
            state_phrase = "If the Delhi/Tihar rule is not retrieved for this answer, "
        lines.append(
            f"{state_phrase}use the Prisons Act source only as the national prison-administration pointer and ask for the applicable State prison rule/manual before demanding a specific interview duration or book entitlement [{prisons}]."
        )
    if article21 is not None:
        lines.append(
            f"If the restriction is arbitrary, discriminatory, or blocks family/lawyer access without reasons, preserve the Article 21 liberty/fairness point for DLSA or High Court review [{article21}]."
        )
    lines.append("**What you can do next**")
    action_cite = delhi_rules if delhi_rules is not None else prisons if prisons is not None else article21
    evidence = (
        "prisoner number, jail name, relationship proof, requested books/book titles, mulaqat date, and refusal/order copy"
        if book_context
        else "prisoner details, relationship proof, failed video-call slot dates/screenshots, server-down message or staff refusal, and requested next slot"
        if _has_any_term(query, ("video call", "video calls", "video slot", "call slot", "server down", "slot failed"))
        else "prisoner details, relationship proof, visitor-list application, address-check/verification proof, and removal or refusal message"
        if _has_any_term(query, ("visitor list", "removed my name", "address check", "address verification"))
        else "prisoner details, relationship proof, requested mulaqat time/frequency, and the refusal/order copy"
    )
    lines.append(
        f"- Submit a written request to the Jail Superintendent with {evidence}; ask for the rule/order and written reasons if refused, then escalate to DLSA, prison-visitors board, or High Court writ route if the refusal is arbitrary or reasons are not given [{action_cite}]."
    )
    return lines


