def _prison_parole_furlough_template_lines(query: str, passages: list[dict]) -> list[str]:
    delhi_rules = _find_passage_index(
        passages,
        title_terms=("delhi prison rules", "delhi prisons rules"),
        anchor_terms=(
            "/rule-1197-1200",
            "/rule-1210-1217",
            "/rule-1220-1226",
            "/rule-1234-1237",
        ),
    )
    prisons = _find_passage_index(
        passages,
        title_terms=("prisons act", "prisons"),
        anchor_terms=("/sec-59",),
    )
    article21 = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-21",),
    )
    if delhi_rules is None and prisons is None and article21 is None:
        return []

    delhi_context = _has_any_term(query, ("tihar", "delhi", "mandoli", "rohini"))
    if not delhi_context:
        delhi_rules = None
    furlough_context = _has_any_term(query, ("furlough", "good conduct", "birthday"))
    custody_parole_context = _has_any_term(query, (
        "custody parole", "emergency parole", "temporary parole",
        "funeral", "last rites", "cremation", "death in family",
    ))
    parole_context = custody_parole_context or _has_any_term(query, (
        "parole", "emergency", "family", "medical", "marriage", "wedding", "death",
    ))
    direct_family_application_context = _has_any_term(query, (
        "no lawyer", "without lawyer", "send application directly", "apply directly",
        "family has card", "family can send", "daughter marriage", "daughter's wedding",
        "sister wedding", "sister's wedding", "wedding card", "marriage card",
    ))
    video_mulaqat_context = _has_any_term(query, (
        "video mulaqat", "video mulakat", "video visit",
        "video call is available", "video call available",
        "family video call", "video call", "video calls",
        "mulaqat is working", "mulakat is working",
    ))
    same_day_emergency_context = custody_parole_context and _has_any_term(query, (
        "tomorrow", "today", "same day", "immediate", "urgent", "cremation",
        "funeral", "last rites",
    ))
    delhi_jail_name = (
        "Rohini jail"
        if _has_any_term(query, ("rohini",))
        else "Mandoli jail"
        if _has_any_term(query, ("mandoli",))
        else "Tihar/Delhi"
    )

    lines = ["**Short answer**"]
    if delhi_rules is not None:
        if custody_parole_context:
            lines.append(
                f"For {delhi_jail_name} custody parole or emergency parole, use the Delhi Prison Rules first: treat it as a time-sensitive prison-release request for a specific family emergency such as cremation, funeral, or last rites, routed through the Jail Superintendent/competent authority, not as domestic violence, property, or ordinary bail [{delhi_rules}]."
            )
            if same_day_emergency_context:
                lines.append(
                    f"For a cremation, funeral, last rites, or other tomorrow/same-day family emergency, mark the application as urgent custody parole and ask for an immediate written decision or reasons for delay [{delhi_rules}]."
                )
        elif furlough_context and not parole_context:
            lines.append(
                f"For Tihar/Delhi furlough, use the Delhi Prison Rules first: furlough is a good-conduct prison-release incentive with eligibility, exclusion, application, and reasoned-order rules; it is different from regular parole [{delhi_rules}]."
            )
        elif parole_context and not furlough_context:
            lines.append(
                f"For Tihar/Delhi parole, use the Delhi Prison Rules first: parole is temporary release for family/social obligations or other listed grounds, and the application route runs through the Jail Superintendent and competent authority [{delhi_rules}]."
            )
        else:
            lines.append(
                f"For Tihar/Delhi parole or furlough, use the Delhi Prison Rules first; parole and furlough have different purposes, eligibility conditions, application papers, and release effects [{delhi_rules}]."
            )
        lines.append(
            f"If parole or furlough is rejected, ask for the written order and reasons; the Delhi source requires fair assessment and reasons, and non-receipt of police verification within time is not by itself a rejection ground [{delhi_rules}]."
        )
    elif prisons is not None:
        non_delhi_place = (
            "Uttar Pradesh"
            if _has_any_term(query, ("uttar pradesh", "up jail", "u.p."))
            else "the State where the jail is located"
        )
        vulnerability = (
            " and attach age/heart-condition medical proof"
            if _has_any_term(query, ("heart", "65", "sixty five", "old", "elderly", "patient"))
            else ""
        )
        state_note = (
            f"For a parole or furlough request in {non_delhi_place}, use Prisons Act Section 59 as the national rule-making pointer: "
            f"file through the Jail Superintendent or jail authority{vulnerability}, but the concrete days, eligibility, police-verification, and form details still come from the applicable State prison/parole/furlough rules or prison manual"
        )
        if delhi_context:
            state_note = "If the Delhi/Tihar rules are not retrieved, do not guess the Delhi parole or furlough threshold; get the Delhi prison rule/order and use Prisons Act only as a general prison-administration starting point"
        lines.append(f"{state_note} [{prisons}].")
        if video_mulaqat_context and parole_context:
            lines.append(
                f"Working video mulaqat or interview access does not decide parole eligibility; parole/furlough is a separate temporary-release application for the wedding or family ground, so keep the mulaqat fact separate from the parole file [{prisons}]."
            )
        if direct_family_application_context:
            lines.append(
                f"For a daughter's or sister's wedding, marriage card, or similar family ground where the family has no lawyer, the family can still submit a written application through the Jail Superintendent; ask DLSA or the jail legal-aid clinic to verify the applicable State prison/parole rule before relying on any exact days or eligibility claim [{prisons}]."
            )

    if article21 is not None:
        lines.append(
            f"If the refusal is arbitrary, unexplained, discriminatory, or ignores serious family/medical grounds, keep an Article 21 fairness/liberty point for DLSA or High Court review after creating the prison record [{article21}]."
        )

    lines.append("**What you can do next**")
    action_cite = delhi_rules if delhi_rules is not None else prisons if prisons is not None else article21
    docs = (
        "conviction/order copy, jail number, sentence and custody calculation, death certificate/cremation or last-rites proof, family relationship proof, address/surety details, and the exact urgent reason for custody parole"
        if delhi_rules is not None and same_day_emergency_context
        else "conviction/order copy, jail number, sentence and custody calculation, annual good-conduct/remission record, prior rejection orders, family/medical/emergency proof, address/surety details, and the exact reason for custody parole, parole, or furlough"
        if delhi_rules is not None
        else "jail number, conviction/order copy, custody calculation, conduct record, state/prison name, furlough/parole reason, age or heart-patient medical proof if relied on, family proof where relevant, and any rejection order"
    )
    action_prefix = (
        "File the urgent written custody-parole application the same day through the Jail Superintendent"
        if same_day_emergency_context
        else "If the family has no lawyer, send the written parole/furlough application directly through the Jail Superintendent"
        if direct_family_application_context
        else "File or renew the written application through the Jail Superintendent"
    )
    lines.append(
        f"- {action_prefix} with {docs}; ask DLSA or the jail legal-aid clinic to check the applicable State rule/manual and challenge an unexplained refusal if needed [{action_cite}]."
    )
    return lines


