def _is_adult_age_record_correction_query(query: str) -> bool:
    q = query.lower()
    adult_context = (
        _has_any_term(q, (
            "18 plus", "18+", "above 18", "over 18", "adult", "major",
            "19 year", "19 years", "19-year", "twenty year", "20 year",
        ))
        or re.search(r"\b(?:age|aged|is|was)\s+(?:18|19|2[0-9]|[3-9][0-9])\b", q) is not None
        or re.search(r"\b(?:18|19|2[0-9]|[3-9][0-9])\s*(?:yr|yrs|year|years)\s*old\b", q) is not None
    )
    wrong_record_context = _has_any_term(q, (
        "wrong dob", "wrong date of birth", "wrong age", "age wrong",
        "old school id", "school id has wrong", "school record wrong",
        "old school certificate wrong", "wrong school certificate",
        "wrong school dob", "fir says minor", "fir shows minor",
        "fir says juvenile", "fir shows juvenile",
        "charge sheet says 17", "chargesheet says 17", "charge-sheet says 17",
        "charge sheet shows 17", "chargesheet shows 17", "charge-sheet shows 17",
        "case paper says 17", "case papers say 17", "case paper shows 17",
        "case papers show 17", "police file says 17", "police file shows 17",
        "wrote minor", "written minor", "shown minor", "minor by mistake",
        "age record", "correct age record", "correct age", "age correction",
        "dob correction", "date of birth correction",
    ))
    criminal_context = _has_any_term(q, (
        "fir", "criminal case", "police picked", "police took", "arrest",
        "arrested", "custody", "remand", "bail", "case paper",
        "case papers", "charge sheet", "chargesheet", "charge-sheet",
    ))
    return adult_context and wrong_record_context and criminal_context


