def _bail_release_delay_template_lines(query: str, passages: list[dict]) -> list[str]:
    bnss_bail = _find_passage_index(
        passages,
        title_terms=("bharatiya nagarik suraksha",),
        anchor_terms=("/sec-480", "/sec-483"),
    )
    crpc_bail = _find_passage_index(
        passages,
        title_terms=("code of criminal procedure",),
        anchor_terms=("/sec-437", "/sec-439"),
    )
    article21 = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-21",),
    )
    primary = bnss_bail if bnss_bail is not None else crpc_bail if crpc_bail is not None else article21
    if primary is None:
        return []
    verification_phrase = (
        "the order allows personal bond but a cash deposit is being demanded"
        if _has_any_term(query, ("personal bond", "cash deposit", "cash demand", "cash security", "deposit cash"))
        else
        "surety verification is pending"
        if _has_any_term(query, ("surety verification", "verification pending", "surety pending", "police verification pending"))
        else "the court release order or e-copy has not reached/been acted on"
        if _has_any_term(query, ("e-copy", "e copy", "copy not received", "not received", "court ordered release"))
        else "the release warrant/order has not been acted on"
        if _has_any_term(query, ("release warrant", "release order", "release memo"))
        else "the jail is not releasing the person after bail"
    )
    lines = ["**Short answer**"]
    lines.append(
        f"If bail has already been granted but {verification_phrase}, treat it as a bail-release implementation problem: the family or lawyer should mention it before the same bail court or court controlling the release order and ask for a written jail/release-warrant status [{primary}]."
    )
    if article21 is not None and article21 != primary:
        lines.append(
            f"Keep the Article 21 liberty point in the file because a person can remain unlawfully deprived of liberty if release is blocked despite a bail order without proper reason [{article21}]."
        )
    lines.append(
        f"Ask specifically whether the e-copy/release warrant reached the jail, whether surety or bond acceptance is pending, and what jail non-release reason is recorded; if unclear, request same-day clarification or direction to the Jail Superintendent through the lawyer/DLSA [{primary}]."
    )
    if _has_any_term(query, ("personal bond", "cash deposit", "cash demand", "cash security", "deposit cash")):
        lines.append(
            f"If the bail order permits release on personal bond, do not accept a clerk-level cash-deposit demand as the final word; ask the same court to clarify or direct the jail/registry on the exact bond condition [{primary}]."
        )
    lines.append("**What you can do next**")
    lines.append(
        f"- Take the High Court/trial-court bail order, e-copy or release-warrant details, surety/bond papers, verification receipt, jail refusal or no-release proof, case/FIR number, court name, and dates to the same court through DLSA or the defence lawyer; request a same-day status/direction to the Jail Superintendent or verification authority [{primary}]."
    )
    return lines


def _bail_surety_hardship_template_lines(query: str, passages: list[dict]) -> list[str]:
    bnss_bail = _find_passage_index(
        passages,
        title_terms=("bharatiya nagarik suraksha",),
        anchor_terms=("/sec-480", "/sec-483"),
    )
    crpc_bail = _find_passage_index(
        passages,
        title_terms=("code of criminal procedure",),
        anchor_terms=("/sec-437", "/sec-439"),
    )
    article21 = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-21",),
    )
    primary = bnss_bail if bnss_bail is not None else crpc_bail if crpc_bail is not None else article21
    if primary is None:
        return []

    amount_match = re.search(r"\b(?:rs\.?|inr)?\s*(\d{4,7})\b", query)
    amount_phrase = f" like {amount_match.group(1)}" if amount_match else ""
    migrant_phrase = "two local sureties for a migrant/no-local-surety family" if _has_any_term(query, ("two local sureties", "local sureties", "migrants", "migrant")) else "an unaffordable surety or bond condition"
    lines = ["**Short answer**"]
    lines.append(
        f"If the court asked for {migrant_phrase}, treat it as a bail-condition hardship problem: ask the same bail court to modify, reduce, or substitute the surety or bond condition instead of leaving the person in jail after bail [{primary}]."
    )
    if article21 is not None and article21 != primary:
        liberty_block = "a high surety amount for a poor family" if _has_any_term(query, ("surety amount high", "high surety", "poor")) else "an unaffordable or impossible local-surety condition"
        lines.append(
            f"Also keep the Article 21 personal-liberty source because {liberty_block} can block actual release even after bail is granted [{article21}]."
        )
    lines.append(
        f"If the issue is two local sureties, migrant family facts, or a high surety amount{amount_phrase}, ask for personal bond, one surety, reduced amount, cash/security alternative, or other condition the court can record on the case facts [{primary}]."
    )
    lines.append("**What you can do next**")
    hardship_docs = "poverty/income proof and proof that the surety amount is too high" if _has_any_term(query, ("surety amount high", "high surety", "poor")) else "income/poverty proof"
    lines.append(
        f"- Take the bail order, exact surety/bond condition, jail non-release proof if any, {hardship_docs}, address proof, family IDs, and migrant/no-local-surety facts to the same bail court through the lawyer, jail legal-aid clinic, or DLSA, and request the court to modify, reduce, or substitute the high surety condition, including personal bond where the facts justify it [{primary}]."
    )
    return lines


