def _birth_certificate_rti_template_lines(query: str, passages: list[dict]) -> list[str]:
    registrar = _find_passage_index(
        passages,
        title_terms=("registration of births and deaths",),
        anchor_terms=("/sec-7",),
    )
    home_birth = _find_passage_index(
        passages,
        title_terms=("registration of births and deaths",),
        anchor_terms=("/sec-8",),
    )
    certificate = _find_passage_index(
        passages,
        title_terms=("registration of births and deaths",),
        anchor_terms=("/sec-12",),
    )
    delayed = _find_passage_index(
        passages,
        title_terms=("registration of births and deaths",),
        anchor_terms=("/sec-13",),
    )
    correction = _find_passage_index(
        passages,
        title_terms=("registration of births and deaths",),
        anchor_terms=("/sec-15",),
    )
    civil_registration = _find_passage_index(
        passages,
        title_terms=("registration of births and deaths",),
    )
    sec6 = _find_passage_index(passages, title_terms=("right to information act",), anchor_terms=("/sec-6",))
    sec7 = _find_passage_index(passages, title_terms=("right to information act",), anchor_terms=("/sec-7",))
    sec19 = _find_passage_index(passages, title_terms=("right to information act",), anchor_terms=("/sec-19",))
    if sec6 is None and civil_registration is None:
        return []
    is_death = _has_any_term(query, ("death certificate", "death registration"))
    record_phrase = "the death certificate" if is_death else "your child's birth certificate" if _has_any_term(query, ("child", "baby", "son", "daughter")) else "the birth certificate"
    birth_context = "" if is_death else " born at home" if _has_any_term(query, ("born at home", "home birth")) else ""
    office_phrase = "panchayat or registrar" if "panchayat" in query else "registrar or municipal office"
    refusal_phrase = (
        " and the official's refusal"
        if _has_any_term(query, ("not giving", "refusing", "refused", "denied", "secretary", "cannot correct"))
        else ""
    )
    if civil_registration is None:
        status_cite = sec6
        lines = [
            "**Short answer**",
            (
                f"For {record_phrase}{birth_context}, use RTI only to ask the {office_phrase} "
                f"for the correction/application status, the reason for refusal, and the rule being applied [{status_cite}]."
            ),
            "**What you can do next**",
            (
                f"- File a written or electronic RTI request for the {'death' if is_death else 'birth'}-certificate file status, noting the "
                f"{'death' if is_death else 'birth'} facts{refusal_phrase} [{status_cite}]."
            ),
        ]
        if sec7 is not None:
            lines.insert(2, f"The public information officer generally has thirty days to provide or reject the information request [{sec7}].")
        if sec19 is not None:
            lines.append(f"- If there is no decision or an improper refusal, file the RTI first appeal to the senior officer route [{sec19}].")
        return lines

    is_correction = _has_any_term(query, ("wrong", "incorrect", "mistake", "cannot correct", "correction", "correct"))
    is_delayed = _has_any_term(query, ("delayed", "late", "not registered", "not giving", "refusing", "refused", "secretary"))
    status_cite = (
        correction if is_correction and correction is not None
        else certificate if certificate is not None and not is_delayed
        else home_birth if home_birth is not None
        else delayed if delayed is not None
        else registrar if registrar is not None
        else civil_registration if civil_registration is not None
        else sec6
    )
    lines = [
        "**Short answer**",
        (
            f"For {record_phrase}{birth_context}, start with the Registration of Births and Deaths Act registrar route and ask the {office_phrase} "
            f"for the correction/application status, the reason for refusal, and the rule being applied [{status_cite}]."
        ),
        "**What you can do next**",
        (
            f"- File a written registration/correction request with the Registrar first, noting the "
            f"{'death' if is_death else 'birth'} facts{refusal_phrase} [{status_cite}]."
        ),
    ]
    if civil_registration is not None:
        lines.insert(1, f"The Registration of Births and Deaths source is the first source to verify for the civil-registration record before treating it as a generic RTI or hospital-service complaint [{civil_registration}].")
    if home_birth is not None and birth_context:
        lines.insert(2, f"For a child born at home, the home-birth reporting source is the operative source for giving the birth particulars to the Registrar [{home_birth}].")
    if certificate is not None:
        lines.insert(2, f"Once registration is complete, the Registrar certificate source is the direct certificate route to check [{certificate}].")
    if delayed is not None and is_delayed:
        lines.insert(3, f"If the birth or death was not reported within the prescribed time, use the delayed-registration source rather than asking only for information under RTI [{delayed}].")
    if sec6 is not None:
        lines.append(
            f"- Use RTI only as a secondary record-status route for the file, written reasons, and copies held by the public authority [{sec6}]."
        )
    if sec7 is not None:
        lines.insert(2, f"The public information officer generally has thirty days to provide or reject the information request [{sec7}].")
    if sec19 is not None:
        lines.append(f"- If there is no decision or an improper refusal, file the RTI first appeal to the senior officer route [{sec19}].")
    return lines


def _kanya_vivah_scheme_template_lines(query: str, passages: list[dict]) -> list[str]:
    scheme = _find_passage_index(passages, title_terms=("kanya vivah", "mukhyamantri kanya vivah"))
