    rti19 = _find_passage_index(passages, title_terms=("right to information",), anchor_terms=("/sec-19",))
    rti_status = rti6 if rti6 is not None else rti7 if rti7 is not None else rti19
    if scheme is None and rti_status is None:
        return []
    state_phrase = "Bihar " if _has_any_term(query, ("bihar", "patna", "gaya", "muzaffarpur")) else "state-specific "
    lines = ["**Kanya Vivah payment status**", "**Short answer**"]
    if scheme is not None:
        if state_phrase == "Bihar ":
            lines.append(
                f"For Bihar Kanya Vivah scheme money, start with the scheme/service source and check the application status, eligibility papers, and marriage-certificate record before treating it as a generic RTI appeal [{scheme}]."
            )
        else:
            lines.append(
                f"Kanya Vivah payment is state-scheme specific: use your State's scheme office/portal first, and use the cited Kanya Vivah service source only as a model of the documents/status fields to verify until the exact State scheme is identified [{scheme}]."
            )
    elif rti_status is not None:
        lines.append(
            f"For Kanya Vivah scheme money not given after the daughter wedding, use the district scheme office or grievance portal for the benefit claim; use RTI only as the record-status route for the public authority holding the payment file [{rti_status}]."
        )
        if rti6 is not None:
            lines.append(
                f"The RTI source says a person seeking information may make a request in writing or through electronic means to the public information officer [{rti6}]."
            )
        elif rti7 is not None:
            lines.append(
                f"The RTI time-limit source is only for getting information/status from the public authority, not for deciding scheme eligibility or payment by itself [{rti7}]."
            )
        elif rti19 is not None:
            lines.append(
                f"The RTI appeal source is only for challenging a missing or improper information reply; it is not the main Kanya Vivah payment grievance route [{rti19}]."
            )
    if scheme is not None and rti6 is not None:
        lines.append(
            f"The RTI source is the statutory request route for obtaining information from the public authority that holds the scheme record [{rti6}]."
        )
    lines.append("**What you can do next**")
    action_cite = scheme if scheme is not None else rti_status
    lines.append(
        f"- Keep the application or beneficiary ID, marriage certificate, eligibility/income papers, bank/passbook details, sanction or rejection/status screenshot, and ask the district social welfare or women-child office for written status, rejection reason, sanction order, and payment file number [{action_cite}]."
    )
    if rti_status is not None:
        lines.append(
            f"- Use RTI only as a record-status route if the office or portal does not answer: ask for the file status, payment/sanction record, rejection reason, and officer holding the scheme file [{rti_status}]."
        )
