def _criminal_defence_bail_floor_template_lines(query: str, route: MatterRoute, passages: list[dict]) -> list[str]:
    special = _criminal_defence_special_source(query, passages)
    procedure = _criminal_defence_procedure_source(query, passages)
    liberty = _find_passage_index(
        passages,
        title_terms=("constitution",),
        anchor_terms=("/sec-21",),
    )
    if special is None and procedure is None and liberty is None:
        return []

    topic = _criminal_defence_topic_phrase(query, route)
    lines = ["**Short answer**"]
    cattle_context = _has_any_term(query, ("cow", "cattle", "buffalo", "smuggling", "transport", "mandi", "slaughter"))
    if cattle_context and procedure is not None:
        pca = _find_passage_index(
            passages,
            title_terms=("prevention of cruelty to animals",),
            anchor_terms=("/sec-11", "/sec-29"),
        )
        transport_rules = _find_passage_index(
            passages,
            title_terms=("transport of animals rules",),
            anchor_terms=("/rules-46-56",),
        )
        animal_support = [idx for idx in (pca, transport_rules) if idx is not None]
        animal_cites = ", ".join(f"[{idx}]" for idx in animal_support)
        special_title = next(
            (
                str(p.get("title") or "").lower()
                for p in passages
                if p.get("index") == special
            ),
            "",
        )
        exact_state_cattle_source = any(
            term in special_title
            for term in ("cow slaughter act", "cattle preservation", "animal preservation")
        )
        if special is not None and exact_state_cattle_source:
            lines.append(
                f"Treat this as a state cattle-preservation accused-procedure issue: verify the FIR/complaint against the state cattle or cow-slaughter source, then use the criminal-procedure source for bail, remand, and court steps [{special}], [{procedure}]."
            )
        elif animal_support:
            lines.append(
                f"Use the Prevention of Cruelty to Animals / Transport of Animals sources for animal-cruelty or transport-condition allegations such as overloading, cruel carriage, veterinary certificate, space, water, feeding, ventilation, or seized-animal custody; they do not replace the exact State cattle-preservation section {animal_cites}."
            )
        if not exact_state_cattle_source:
            lines.append(
                f"I do not have the exact state Cattle Preservation/Animal Preservation Act source in the retrieved index for this cow/buffalo transport allegation, so do not treat a judgment or generic bail/procedure text as the controlling State Act [{procedure}]."
            )
        if special is not None and special not in animal_support and not exact_state_cattle_source:
            lines.append(
                f"A retrieved cattle/animal-transport judgment can help identify vehicle seizure, animal custody, or state-law issues, but it does not replace the FIR's exact state Act and section text [{special}]."
            )
        lines.append(
            f"For the accused-side arrest question, use the criminal-procedure source only for custody, FIR, remand, and bail steps while a lawyer verifies the state cattle-preservation or animal-cruelty section from the FIR and State source [{procedure}]."
        )
        lines.append("**What you can do next**")
        action_cites = ", ".join(f"[{idx}]" for idx in [*animal_support, procedure])
        lines.append(
            f"- Collect the FIR/complaint, seized animal/vehicle papers, ownership and mandi transport proof, veterinary certificate or permit documents if any, arrest/remand papers, transport-condition facts, and the exact state-law sections; take them to DLSA or a criminal lawyer for the trial court, Special Court, High Court, or legal-aid route and state-law verification {action_cites}."
        )
        return lines
    source_line = _source_title_line(passages, special, prefix="Special source to verify first")
    if source_line:
        lines.append(source_line)
    if special is not None:
        lines.append(
            f"Treat this as {topic}; check the special-statute or offence source against the exact FIR, complaint, seizure memo, quantity, age, or role alleged before treating it as ordinary bail advice [{special}]."
        )
    if procedure is not None:
        lines.append(
            f"Use the BNSS/CrPC procedure source for arrest, notice, custody, default-bail, regular-bail, anticipatory-bail, or quashing steps only after fixing the incident date and current case stage [{procedure}]."
        )
    if liberty is not None and _has_any_term(query, (
        "long custody", "no trial", "trial delay", "medical", "sick", "pregnant",
        "adult jail", "minor", "juvenile", "under 18", "3 years", "3 yrs",
    )):
        lines.append(
            f"Keep Article 21 as a liberty, medical-care, or delay point, but do not use it as a substitute for the special Act or custody-date calculation [{liberty}]."
        )
    lines.append("**What you can do next**")
    action_cite = procedure if procedure is not None else special if special is not None else liberty
    lines.append(
        f"- Collect the FIR/complaint, offence sections, incident date, arrest/notice status, remand and bail orders, charge-sheet or extension status, and the special fact such as quantity, age proof, medical record, caste/status, state law, or alleged role; take those papers to DLSA or a criminal lawyer before moving the trial court, Special Court, High Court, or legal-aid route [{action_cite}]."
    )
    return lines


