def _criminal_defence_special_source(query: str, passages: list[dict]) -> int | None:
    q = query.lower()
    candidates: list[tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]] = [
        (("ndps", "ganja", "charas", "mdma", "heroin", "cannabis", "weed", "bhang"), ("narcotic drugs and psychotropic substances",), ()),
        (("uapa", "terror", "nia", "43d"), ("unlawful activities", "prevention act 1967", "uapa"), ()),
        (("pmla", "ed summons", "ed notice", "enforcement directorate", "ecir", "money laundering"), ("prevention of money laundering",), ()),
        (("juvenile", "minor", "under 18", "adult jail", "observation home", "pocso"), ("juvenile justice",), ()),
        (("pocso", "minor girl", "minor boy", "child sexual"), ("protection of children from sexual offences",), ()),
        (("itpa", "pita", "immoral traffic", "spa", "massage"), ("immoral traffic",), ()),
        (("sc/st", "atrocity", "scheduled caste", "scheduled tribe", "dalit", "adivasi"), ("scheduled castes", "scheduled tribes", "atrocities"), ()),
        (("prohibition", "excise", "liquor", "alcohol", "sharab"), ("bihar prohibition", "state excise", "prohibition"), ()),
        (
            ("cattle", "cow", "buffalo", "slaughter", "gau", "gauraksha"),
            (
                "cattle preservation", "cow slaughter", "animal preservation",
                "multani hanifbhai", "chhatrapati shivaji gaushala",
                "laxmi narain modi", "prevention of cruelty to animals",
                "transport of animals rules",
            ),
            (),
        ),
        (("forest", "tendu", "minor forest produce"), ("forest rights", "indian forest", "forest"), ()),
        (("cyber", "it act", "section 67", "obscene", "online"), ("information technology",), ()),
        (("promised marriage", "promise marriage", "rape case", "498a", "false case", "false fir", "assault"), ("bharatiya nyaya", "indian penal"), ()),
    ]
    for triggers, title_terms, anchor_terms in candidates:
        if not any(term in q for term in triggers):
            continue
        found = _find_passage_index(passages, title_terms=title_terms, anchor_terms=anchor_terms)
        if found is not None:
            return found
    return None


