def _is_ancestral_land_sale_query(text: str) -> bool:
    property_context = _has_any_term(text, ("ancestral", "dada", "grandfather", "grandfather's", "father name", "father's name")) and _has_any_term(text, ("land", "plot", "house", "property"))
