def _is_credit_identity_misuse_query(text: str) -> bool:
    # A disputed signature on a loan secured against a home/property needs the
    # dedicated forged-loan route.  It has a different evidence packet and a
    # parallel bank-record, police, and property-document response; do not
    # collapse it into generic credit-report or identity correction.
    if _is_bank_property_document_fraud_query(text):
        return False
    credit = _has_any_term(text, (
        "loan", "fake loan", "nbfc", "finance company", "cibil",
        "credit report", "credit score", "credit bureau",
    ))
    identity_misuse = _has_any_term(text, (
        "signature not mine", "not my signature", "fake signature",
        "did not sign", "didn't sign", "forged", "forgery",
        "documents but signature", "loan showing on my documents",
        "loan showing in my documents", "opened in my name",
        "without my consent",
    ))
    return credit and identity_misuse


