def _promote_safe_route_next_step(
    v: SentenceVerification,
    route: MatterRoute,
    pending_header: SentenceVerification | None,
) -> SentenceVerification:
    """Let server-authored action-pack bullets pass as weak support.

    The legal source often proves the forum/provision but not the operational
    user step ("keep screenshots", "collect jewellery receipts"). Those steps
    come from our deterministic route/action-pack layer, so an entailment
    scorer can mark them unsupported even when they are the product answer the
    user needs. Keep this narrowly scoped to cited bullets immediately under
    the server's "What you can do next" header.
    """
    if v.status not in (SentenceStatus.UNSUPPORTED, SentenceStatus.WEAK_SUPPORT):
        return v
    if not v.citations:
        return v
    if not _is_safe_template_next_step(v.text, route, pending_header):
        return v
    return SentenceVerification(
        text=v.text,
        status=SentenceStatus.WEAK_SUPPORT,
        citations=v.citations,
        entailment_score=v.entailment_score,
        reason="server-authored safe route next step",
        auto_cited=False,
    )


def _promote_safe_template_source_bridge(
    v: SentenceVerification,
    route: MatterRoute,
) -> SentenceVerification:
    if v.status not in (SentenceStatus.UNSUPPORTED, SentenceStatus.WEAK_SUPPORT):
        return v
    if not v.citations:
        return v
    if not _is_safe_template_source_bridge(v.text, route):
        return v
    return SentenceVerification(
        text=v.text,
        status=SentenceStatus.WEAK_SUPPORT,
        citations=v.citations,
        entailment_score=v.entailment_score,
        reason="server-authored safe source bridge",
        auto_cited=False,
    )


def _promote_reviewed_workflow_contract_line(
    v: SentenceVerification,
    workflow_result: WorkflowTemplateResult | None,
    template_lines: list[str],
) -> SentenceVerification:
    """Allow reviewed, source-gated workflow contract lines to survive NLI drift.

    The general NLI/verifier can under-score deterministic workflow sentences
    that combine a source-backed legal rule with user-facing routing language.
    This promotion is intentionally narrow: it only applies when the selected
    workflow is one of the high-risk reviewed contracts, the rendered template
    is exactly that workflow, and the sentence already has valid citations.
    """
    if v.status not in (SentenceStatus.UNSUPPORTED, SentenceStatus.WEAK_SUPPORT):
        return v
    if not v.citations or workflow_result is None:
        return v
    if not workflow_contract_promotes_verifier(workflow_result):
        return v
    if template_lines != workflow_result.lines:
        return v
    reviewed_lines = {
        line.strip()
        for line in workflow_result.lines
        if line.strip() and not _is_deferred_template_header(line)
    }
    if v.text.strip() not in reviewed_lines:
        return v
    return SentenceVerification(
        text=v.text,
        status=SentenceStatus.OK,
        citations=v.citations,
        entailment_score=v.entailment_score,
        reason="reviewed workflow contract line",
        auto_cited=False,
    )


def _strip_model_terminal_sections(text: str) -> str:
    """Remove model-authored Sources/Disclaimer blocks before segmentation."""
    text = re.sub(
        r"(?i)(?<!\n)\s+((?:#{1,6}\s*)?(?:\*\*\s*)?"
        r"(?:sources?|references?|bibliography|disclaimer)"
        r"(?:\s*\*\*)?\s*:?)",
        r"\n\1",
        text,
    )
    kept: list[str] = []
    skipping = False
    for line in text.splitlines():
        stripped = line.strip()
        if _SOURCES_HEADER_RE.match(stripped) or _DISCLAIMER_HEADER_RE.match(stripped):
            skipping = True
            continue
        if skipping and _MAJOR_HEADER_RE.match(stripped):
            skipping = False
        if not skipping:
            kept.append(line)
    return "\n".join(kept)


_OFFICIAL_SOURCE_TYPES = {
    "bare_act", "rule", "regulation", "scheme", "guideline", "circular", "notification",
}

_ACTION_WORDS = (
    "apply", "application", "complaint", "complain", "appeal", "petition",
    "file", "filing", "approach", "authority", "tribunal", "court",
    "magistrate", "collector", "officer", "ombudsman", "commission",
    "forum", "notice", "report", "register", "grievance",
)


def _actionable_source_intro_line_for_sentence(
    route: MatterRoute,
    passages: list[dict],
    state: dict,
    verification: SentenceVerification,
    *,
    query: str = "",
) -> str | None:
    """Prepend an official/actionable source when an answer would lead with a judgment.

    Judgments are useful support, but broad layperson routes need the first
    visible citation to anchor the forum/procedure/statute path where possible.
    This only fires when the sentence about to be shown cites a judgment and
    the answer has not yet cited an official source.
    """
    if not _route_requires_actionable_source_first(route):
        return None
    if state.get("actionable_source_floor_emitted"):
        return None
    if _answer_has_cited_actionable_source(state, passages):
        return None
    if not verification.citations:
        return None

    by_idx = _passages_by_index(passages)
    cited_passages = [by_idx[idx] for idx in verification.citations if idx in by_idx]
    if not cited_passages:
        return None
    if any(_is_actionable_contract_source(p) for p in cited_passages):
        return None
    if not any(_is_judgment_source(p) for p in cited_passages):
        return None

    passage = _first_actionable_source_for_route(route, passages, query=query)
    if passage is None:
        return None
    if route.label == "Writ / constitutional remedy procedure":
        writ_source_blob = _normalize_match_text(
            " ".join(
                str(passage.get(field) or "")
                for field in ("title", "anchor", "text")
            )
        )
        if "article 226" not in writ_source_blob and "/sec-226" not in str(passage.get("anchor") or "").lower():
            return None
    idx = passage.get("index")
    if not isinstance(idx, int):
        return None
    ref = _source_reference_label(passage)
    if not ref:
        return None
    role = _actionable_source_role(route)
    return f"Start with the {role} before relying on judgments: {ref} [{idx}]."


def _route_requires_actionable_source_first(route: MatterRoute) -> bool:
    label = route.label.lower()
    if route.category == "custody_compensation":
        return False
    if any(term in label for term in (
        "anganwadi honorarium",
        "habeas",
        "quashing",
        "constitutional compensation",
        "handcuff",
        "partner-choice",
        "adult choice",
    )):
        return False
    if route.action_pack is None and route.category not in {
        "banking_credit_dispute",
        "police_fir",
        "property_tenancy",
        "business_contract_partnership",
        "consumer",
        "education_rights",
        "employment_wages",
        "family_domestic",
        "general_legal",
        "motor_accident_claims",
        "social_welfare_identity",
    }:
        return False
    return True


def _actionable_source_role(route: MatterRoute) -> str:
    roles = {
        "banking_credit_dispute": "bank/RBI complaint source",
        "police_fir": "FIR/refusal procedure source",
        "business_contract_partnership": "civil recovery/contract source",
        "property_tenancy": "property or tenancy source",
        "consumer": "consumer complaint source",
        "education_rights": "school-rights source",
        "employment_wages": "employment/wage source",
        "family_domestic": "family-law/protection source",
        "general_legal": "baseline civil/procedure source",
        "motor_accident_claims": "motor-accident claim source",
        "cyber_fraud_or_harassment": "cyber/electronic-record source",
        "social_welfare_identity": "scheme or identity-grievance source",
        "drug_treatment_support": "treatment/de-addiction source",
    }
    return roles.get(route.category, "official source for this route")


def _answer_has_cited_actionable_source(state: dict, passages: list[dict]) -> bool:
    cited = set(state.get("emitted_citation_indices") or set())
    by_idx = _passages_by_index(passages)
    return any(_is_actionable_contract_source(by_idx[idx]) for idx in cited if idx in by_idx)


def _first_actionable_source_for_route(route: MatterRoute, passages: list[dict], *, query: str = "") -> dict | None:
    if route.label == "Writ / constitutional remedy procedure":
        article226 = next((
            passage for passage in _official_passages_for_contract(passages)
            if "constitution" in str(passage.get("title") or "").lower()
            and (
                "/sec-226" in str(passage.get("anchor") or "").lower()
                or "article 226" in _normalize_match_text(str(passage.get("text") or ""))
            )
        ), None)
        if article226 is not None:
            return article226
    for passage in _official_passages_for_contract(passages):
        if not _is_actionable_contract_source(passage):
            continue
        if _should_skip_contract_source_line(route, _source_pack_key(passage), set()):
            continue
        if _should_skip_unrelated_source_excerpt(route, passage, query=query):
            continue
        return passage
    return None


def _passages_by_index(passages: list[dict]) -> dict[int, dict]:
    return {
        int(p["index"]): p
        for p in passages
        if isinstance(p.get("index"), int)
    }


def _answer_contract_lines(
    route: MatterRoute,
    passages: list[dict],
    state: dict,
    plan: MatterPlan | None = None,
    query: str = "",
    source_floor_only: bool = False,
) -> list[str]:
    """Server-side floor for answers that under-cite retrieved law.

    The model is still allowed to write the main explanation, but broad evals
    showed a recurring product failure: retrieval surfaces the right Act while
    the final answer cites only a judgment, or omits a concrete next-step
    section. This post-generation floor emits only conservative source-reference
    lines and route-authored action hints. It deliberately avoids raw statute
    excerpts because bare Act chunks often contain split definitions,
    illustrations, or unrelated procedure fragments.
    """
    official = _official_passages_for_contract(passages)
    if not official:
        return []

    lines: list[str] = []
    cited = set(state.get("emitted_citation_indices") or set())
    planned_seen = set(state.get("seen_sentences") or set())
    official_by_idx = {
        p.get("index"): p
        for p in official
        if isinstance(p.get("index"), int)
    }
    cited_source_keys = {
        _source_pack_key(p)
        for idx, p in official_by_idx.items()
        if idx in cited and _source_pack_key(p)
    }

    if source_floor_only:
        route_required_candidates = _route_required_source_floor_passages(
            route,
            official,
            cited,
            cited_source_keys,
            query=query,
            plan=plan,
        )
        required_budget = 4 if route.category in {
            "banking_credit_dispute",
            "family_domestic",
            "property_tenancy",
            "reproductive_rights_mtp",
            "senior_citizen",
        } else 3
        for passage in _dedupe_passages_by_index(route_required_candidates):
            if len(lines) >= required_budget:
                break
            line = _source_excerpt_line(passage)
            if not line:
                continue
            normalized = _normalize_for_dedupe(line)
            if normalized in planned_seen:
                continue
            lines.append(line)
            planned_seen.add(normalized)
        return lines

    if route.category == "senior_citizen" and _has_any_term(query, (
        "gift", "gifted", "gift deed", "transfer", "transferred", "settlement deed",
    )) and _has_any_term(query, (
        "food", "medicine", "medical", "care", "basic amenities",
        "physical needs", "stopped", "not maintaining", "neglect",
    )):
        senior23 = _find_passage_index(
            passages,
            title_terms=("parents and senior citizens", "senior citizens"),
            anchor_terms=("/sec-23",),
        )
        tpa_gift = _find_passage_index(
            passages,
            title_terms=("transfer of property",),
            anchor_terms=("/sec-122", "/sec-123", "/sec-126"),
        )
        senior_transfer_lines: list[tuple[int | None, str]] = []
        if senior23 is not None and senior23 not in cited:
            senior_transfer_lines.append((
                senior23,
                f"Because the house was gifted or transferred and food, medicine, care, or basic needs then stopped, ask the Maintenance Tribunal to check Senior Citizens Act Section 23 transfer-void relief before treating it as only a maintenance complaint [{senior23}].",
            ))
        if tpa_gift is not None and tpa_gift not in cited:
            senior_transfer_lines.append((
                tpa_gift,
                f"Also keep the registered gift-deed and Transfer of Property Act record in the file for deed validity, registration, or revocation terms; that document lane is secondary to the Senior Citizens Tribunal route when Section 23 facts fit [{tpa_gift}].",
            ))
        for idx, line in senior_transfer_lines:
            normalized = _normalize_for_dedupe(line)
            if normalized in planned_seen:
                continue
            lines.append(line)
            planned_seen.add(normalized)
            if isinstance(idx, int):
                cited.add(idx)
                passage = official_by_idx.get(idx)
                source_key = _source_pack_key(passage) if passage else ""
                if source_key:
                    cited_source_keys.add(source_key)

    for passage in _plan_must_cite_passages(route, plan, official, cited, query=query):
        line = _source_excerpt_line(passage)
        if not line:
            continue
        normalized = _normalize_for_dedupe(line)
        if normalized in planned_seen:
            continue
        idx = passage.get("index")
        lines.append(line)
        planned_seen.add(normalized)
        if isinstance(idx, int):
            cited.add(idx)
        source_key = _source_pack_key(passage)
        if source_key:
            cited_source_keys.add(source_key)

    if route.category == "social_welfare_identity" and _is_aadhaar_pension_identity_block_query(query):
        aadhaar_idx = _find_passage_index(
            passages,
            title_terms=("aadhaar",),
            anchor_terms=("aadhaar-2016", "/sec-59", "/sec-7", "/sec-8"),
        )
        pension_idx = _find_passage_index(
            passages,
            title_terms=("national social assistance", "pension", "scheme"),
            anchor_terms=("nsap", "pension"),
        )
        if aadhaar_idx is not None and pension_idx is not None:
            identity_proof = _aadhaar_pension_identity_proof_phrase(query)
            line = (
                f"For the pension block, keep {identity_proof}, pension or beneficiary ID, "
                f"bank/passbook proof, and file both an Aadhaar correction request and a pension-scheme grievance [{aadhaar_idx}][{pension_idx}]."
            )
            normalized = _normalize_for_dedupe(line)
            if normalized not in planned_seen:
                lines.append(line)
                planned_seen.add(normalized)
                cited.update({aadhaar_idx, pension_idx})
                for idx in (aadhaar_idx, pension_idx):
                    passage = official_by_idx.get(idx) or _passages_by_index(passages).get(idx)
                    source_key = _source_pack_key(passage) if passage else ""
                    if source_key:
                        cited_source_keys.add(source_key)

    if route.category == "police_fir" and _is_simple_assault_fir_delay_query(query):
        bns_damage = _find_passage_index(
            passages,
            title_terms=("bharatiya nyaya",),
            anchor_terms=("/sec-324", "/sec-326", "/sec-287"),
        )
        bns_hurt = _find_passage_index(
            passages,
            title_terms=("bharatiya nyaya",),
            anchor_terms=("/sec-115", "/sec-117", "/sec-118", "/sec-125"),
        )
        damage_context = _has_any_term(query, ("broke my", "broken", "damage", "damaged", "scooter mirror", "vehicle mirror"))
        bns_idx = bns_damage if damage_context and bns_damage is not None else bns_hurt
        if bns_idx is not None and bns_idx not in cited:
            line = (
                f"For the property-damage facts, separately match the incident date, photos, repair proof, and witnesses to the BNS mischief/property-damage source before naming the final offence section [{bns_idx}]."
                if damage_context
                else f"For the assault or injury facts, separately match the incident date, medical papers, and witness proof to the BNS hurt/grievous-hurt source before naming the final offence section [{bns_idx}]."
            )
            normalized = _normalize_for_dedupe(line)
            if normalized not in planned_seen:
                lines.append(line)
                planned_seen.add(normalized)
                cited.add(bns_idx)
                passage = official_by_idx.get(bns_idx) or _passages_by_index(passages).get(bns_idx)
                source_key = _source_pack_key(passage) if passage else ""
                if source_key:
                    cited_source_keys.add(source_key)

    required_source_keys: list[str] = []
    for passage in official:
        key = _source_pack_key(passage)
        if passage.get("required_source_pack") and key and key not in required_source_keys:
            required_source_keys.append(key)
    missing_required_keys = [key for key in required_source_keys if key not in cited_source_keys]
    route_required_candidates = _route_required_source_floor_passages(
        route,
        official,
        cited,
        cited_source_keys,
        query=query,
        plan=plan,
    )
    required_budget = 4 if route.category in {
        "banking_credit_dispute",
        "family_domestic",
        "property_tenancy",
        "reproductive_rights_mtp",
        "senior_citizen",
    } else 3
    if (
        state.get("server_template_used")
        and state.get("saw_next_step_sentence")
        and cited_source_keys
        and route.category in {
            "banking_credit_dispute",
            "business_contract_partnership",
            "consumer",
            "business_license_compliance",
            "land_revenue_records",
            "property_tenancy",
            "succession_inheritance",
        }
    ):
        source_budget = 0
    elif (
        route.label == "Tribal land transfer / restoration"
        and cited_source_keys
        and state.get("saw_next_step_sentence")
    ):
        source_budget = 0
    elif (
        route.category == "employment_wages"
        and state.get("saw_next_step_sentence")
        and any(
            idx in cited
            and "provident" in str(p.get("title") or "").lower()
            for idx, p in official_by_idx.items()
        )
    ):
        source_budget = 0
    elif (
        route.category == "employment_wages"
        and _is_non_compete_query(query)
        and state.get("saw_next_step_sentence")
        and any(
            idx in cited
            and "contract" in str(p.get("title") or "").lower()
            for idx, p in official_by_idx.items()
        )
    ):
        source_budget = 0
    elif (
        route.category == "ibc_nclt"
        and state.get("saw_next_step_sentence")
        and any(
            idx in cited
            and "insolvency" in str(p.get("title") or "").lower()
            for idx, p in official_by_idx.items()
        )
    ):
        source_budget = 0
    elif (
        route.label in {"Spousal assault / financial-control complaint", "Spousal sexual coercion / safety support"}
        and cited_source_keys
        and state.get("saw_next_step_sentence")
    ):
        source_budget = 0
    elif cited_source_keys and state.get("saw_next_step_sentence") and int(state.get("emitted") or 0) >= 3:
        source_budget = 0 if len(cited_source_keys) >= 3 else min(1, len(missing_required_keys))
    else:
        source_budget = max(max(0, 2 - len(cited_source_keys)), min(required_budget, len(missing_required_keys)))
    if route_required_candidates:
        source_budget = max(source_budget, min(required_budget, len(route_required_candidates)))

    # Cite official/statutory source families the model skipped. Keep this
    # narrow: broad required packs often include fallbacks, and dumping every
    # official source makes the answer drift away from the user's problem.
    added_source_lines = 0
    source_floor_candidates = _dedupe_passages_by_index([*route_required_candidates, *official])
    route_required_candidate_indices = {
        int(p["index"])
        for p in route_required_candidates
        if isinstance(p.get("index"), int)
    }
    for passage in source_floor_candidates:
        if added_source_lines >= source_budget:
            break
        idx = passage.get("index")
        if not isinstance(idx, int) or idx in cited:
            continue
        source_key = _source_pack_key(passage)
        is_route_required_candidate = idx in route_required_candidate_indices
        if not is_route_required_candidate and _should_skip_contract_source_line(route, source_key, cited_source_keys):
            continue
        if _should_skip_unrelated_source_excerpt(route, passage, query=query):
            continue
        if not is_route_required_candidate and source_key and source_key in cited_source_keys:
            continue
        line = _source_excerpt_line(passage)
        if not line:
            continue
        normalized = _normalize_for_dedupe(line)
        if normalized in planned_seen:
            continue
        lines.append(line)
        planned_seen.add(normalized)
        cited.add(idx)
        if source_key:
            cited_source_keys.add(source_key)
        added_source_lines += 1

    needs_next_step = not state.get("saw_next_step_header") or not state.get("saw_next_step_sentence")
    if needs_next_step:
        action_passages = passages if route.label == "Writ / constitutional remedy procedure" else official
        action_line = _route_action_line(route, action_passages, query=query) or _plan_action_line(plan, official)
        if action_line and _normalize_for_dedupe(action_line) not in planned_seen:
            lines.append("**What you can do next**")
            lines.append(action_line)

    return lines


def _official_passages_for_contract(passages: list[dict]) -> list[dict]:
    def score(p: dict) -> tuple[int, float, int, int, int]:
        source_type = str(p.get("source_type") or "").lower()
        title = str(p.get("title") or "").lower()
        anchor = str(p.get("anchor") or "").lower()
        required = 0 if p.get("required_source_pack") else 1
        priority = -float(p.get("required_source_priority") or 0.0)
        official = 0 if _is_official_contract_source(p) else 1
        judgment = 1 if source_type.endswith("judgment") or " versus " in title or " v. " in title else 0
        useful_anchor = 0 if "/sec-" in anchor or "#sec-" in anchor or "section" in title else 1
        return (required, priority, official, judgment, useful_anchor)

    official = [p for p in passages if _is_official_contract_source(p)]
    return sorted(official, key=lambda p: (*score(p), int(p.get("index") or 999)))


def _route_required_source_floor_passages(
    route: MatterRoute,
    official: list[dict],
    cited: set[int],
    cited_source_keys: set[str],
    *,
    query: str = "",
    plan: MatterPlan | None = None,
) -> list[dict]:
    """Prioritize retrieved sources the selected route itself says are required.

    This plugs the answer-layer hole where retrieval found the controlling Act
    but the visible answer cited only a judgment or generic fallback source.
    """
    required_sources = (
        [entry.source for entry in plan.authority_ledger if entry.must_cite]
        if plan is not None and route.label == "Caste certificate rejection / appeal"
        else list(route.required_sources)
    )
    if not official or not required_sources:
        return []

    out: list[dict] = []
    seen_indices: set[int] = set()
    for required_source in required_sources:
        regime_components = _criminal_regime_required_components(
            required_source,
            official,
            query=query,
        )
        if regime_components is not None:
            matches = regime_components
        elif should_enforce_required_source(required_source, query=query):
            matches = _required_source_floor_matches(required_source, official, query=query)
        else:
            continue
        for passage in matches:
            idx = passage.get("index")
            if not isinstance(idx, int) or idx in cited or idx in seen_indices:
                continue
            if _should_skip_unrelated_source_excerpt(route, passage, query=query):
                continue
            out.append(passage)
            seen_indices.add(idx)
    return out


def _required_source_floor_matches(
    required_source: str,
    official: list[dict],
    *,
    query: str = "",
) -> list[dict]:
    regime_components = _criminal_regime_required_components(
        required_source,
        official,
        query=query,
    )
    if regime_components is not None:
        return regime_components
    passage = best_source_match(required_source, official, query=query)
    if passage is None:
        return []
    if isinstance(passage.get("index"), int):
        return [passage]
    if str(passage.get("source_type") or "").lower() != "aggregate":
        return []
    return _aggregate_required_source_components(required_source, official, passage, query=query)


def _aggregate_required_source_components(
    required_source: str,
    official: list[dict],
    aggregate: dict,
    *,
    query: str = "",
) -> list[dict]:
    aggregate_components = _aggregate_components_by_anchor(aggregate, official)
    if aggregate_components:
        return aggregate_components

    regime_components = _criminal_regime_required_components(
        required_source,
        official,
        query=query,
    )
    if regime_components is not None:
        return regime_components
    return []


def _criminal_regime_required_components(
    required_source: str,
    official: list[dict],
    *,
    query: str = "",
) -> list[dict] | None:
    """Resolve a date-dependent criminal requirement as one coherent regime."""
    lower = str(required_source or "").lower()
    has_bns = _source_requirement_has_any(lower, ("bns", "bharatiya nyaya"))
    has_bnss = _source_requirement_has_any(lower, ("bnss", "bharatiya nagarik"))
    has_ipc = _source_requirement_has_any(lower, ("ipc", "indian penal"))
    has_crpc = _source_requirement_has_any(lower, ("crpc", "criminal procedure"))
    if not (has_bns and has_bnss and has_ipc and has_crpc):
        return None

    bns_item = _preferred_bns_source_for_query(official, query)
    bnss_item = _first_source_matching_requirement(official, ("bnss", "bharatiya nagarik"))
    ipc_item = _first_source_matching_requirement(official, ("ipc", "indian penal"))
    crpc_item = _first_source_matching_requirement(official, ("crpc", "criminal procedure"))
    current_pair = [p for p in (bns_item, bnss_item) if p is not None]
    old_pair = [p for p in (ipc_item, crpc_item) if p is not None]

    old_regime = _query_points_to_old_criminal_regime_for_floor(query)
    new_regime = _query_points_to_new_criminal_regime_for_floor(query)
    if _query_has_explicit_pre_cutover_2024_date(query) or (old_regime and not new_regime):
        return old_pair if len(old_pair) == 2 else []
    if len(current_pair) == 2:
        return current_pair
    return old_pair if len(old_pair) == 2 else []


def _preferred_bns_source_for_query(official: list[dict], query: str) -> dict | None:
    """Choose a retrieved BNS passage that matches the user's criminal fact."""
    candidates = [
        passage
        for passage in official
        if _source_requirement_has_any(_passage_source_blob(passage), ("bns", "bharatiya nyaya"))
    ]
    if not candidates:
        return None
    q = query.lower()
    if _has_any_term(q, ("extort", "blackmail", "ransom", "demand money")):
        extortion = next(
            (
                passage
                for passage in candidates
                if "/sec-308" in str(passage.get("anchor") or "").lower()
                or "extortion" in _passage_source_blob(passage)
            ),
            None,
        )
        if extortion is not None:
            return extortion
    return candidates[0]


def _aggregate_components_by_anchor(aggregate: dict, official: list[dict]) -> list[dict]:
    anchors = [
        anchor.strip().lower()
        for anchor in str(aggregate.get("anchor") or "").split(";")
        if anchor.strip()
    ]
    if not anchors:
        return []
    out: list[dict] = []
    seen_indices: set[int] = set()
    for anchor in anchors:
        passage = next((
            p for p in official
            if isinstance(p.get("index"), int)
            and int(p["index"]) not in seen_indices
            and str(p.get("anchor") or "").strip().lower() == anchor
        ), None)
        if passage is None:
            continue
        out.append(passage)
        seen_indices.add(int(passage["index"]))
    return out if len(out) == len(anchors) else []


def _source_requirement_has_any(text: str, terms: tuple[str, ...]) -> bool:
    return any(re.search(rf"\b{re.escape(term)}\b", text) for term in terms)


def _first_source_matching_requirement(official: list[dict], terms: tuple[str, ...]) -> dict | None:
    for passage in official:
        blob = _passage_source_blob(passage)
        if any(re.search(rf"\b{re.escape(term)}\b", blob) for term in terms):
            return passage
    return None


def _query_points_to_old_criminal_regime_for_floor(query: str) -> bool:
    q = query.lower()
    return bool(
        re.search(r"\b(?:19|20)(?:0\d|1\d|2[0-3])\b", q)
        or _query_has_explicit_pre_cutover_2024_date(q)
        or "ipc" in q
        or "crpc" in q
    )


def _query_has_explicit_pre_cutover_2024_date(query: str) -> bool:
    return re.search(
        r"\b(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?)\s+2024\b",
        query.lower(),
    ) is not None


def _query_points_to_new_criminal_regime_for_floor(query: str) -> bool:
    q = query.lower()
    return bool(
        re.search(r"\b202[5-9]\b", q)
        or re.search(r"\b(?:jul(?:y)?|aug(?:ust)?|sep(?:tember)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s+2024\b", q)
        or "bns" in q
        or "bnss" in q
    )


def _dedupe_passages_by_index(passages: list[dict]) -> list[dict]:
    out: list[dict] = []
    seen_indices: set[int] = set()
    for passage in passages:
        idx = passage.get("index") if isinstance(passage, dict) else None
        if isinstance(idx, int):
            if idx in seen_indices:
                continue
            seen_indices.add(idx)
        out.append(passage)
    return out


def _source_pack_key(passage: dict) -> str:
    pack = str(passage.get("required_source_pack") or "").strip().lower()
    if pack:
        return pack
    return re.sub(
        r"\s+",
        " ",
        str(passage.get("statute_short") or passage.get("title") or "").strip().lower(),
    )


def _passage_source_blob(passage: dict) -> str:
    return " ".join(
        str(passage.get(field) or "").lower()
        for field in ("title", "statute_short", "anchor", "required_source_pack", "source_type")
    )


def _looks_like_asha_source_blob(blob: str) -> bool:
    return (
        "asha" in blob
        or "national health mission" in blob
        or "nhm" in blob
        or "nrhm" in blob
    )


def _looks_like_anganwadi_source_blob(blob: str) -> bool:
    return (
        "anganwadi" in blob
        or "icds" in blob
        or "ameerbi" in blob
        or "maniben" in blob
        or "child development" in blob
        or "women and child" in blob
        or "wcd" in blob
    )


def _plan_must_cite_passages(
    route: MatterRoute,
    plan: MatterPlan | None,
    official: list[dict],
    cited: set[int],
    *,
    query: str = "",
    limit: int = 2,
) -> list[dict]:
    if plan is None or not official:
        return []

    out: list[dict] = []
    seen_indices: set[int] = set()
    for entry in plan.authority_ledger:
        if not entry.must_cite or not entry.act:
            continue
        if entry.act == "date-dependent criminal regime":
            continue
        already_cited = any(
            isinstance(p.get("index"), int)
            and p.get("index") in cited
            and _plan_authority_matches_passage(entry.act, entry.section, p)
            for p in official
        )
        if already_cited:
            continue
        passage = next(
            (
                p for p in official
                if isinstance(p.get("index"), int)
                and p.get("index") not in cited
                and int(p.get("index")) not in seen_indices
                and not _should_skip_contract_source_line(route, _source_pack_key(p), set())
                and not _should_skip_unrelated_source_excerpt(route, p, query=query)
                and _plan_authority_matches_passage(entry.act, entry.section, p)
            ),
            None,
        )
        if passage is None:
            continue
        out.append(passage)
        seen_indices.add(int(passage["index"]))
        if len(out) >= limit:
            break
    return out


